local _, GQ = ...

-- Quest story paragraphs, keyed by the exact English paragraph.
if GQ.ActiveLocale ~= "deDE" then
    return
end

local text = GQ.LocaleText
for k, v in pairs({
    ["Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge."] = "Garrick Padfoot – ein Halsabschneider, der unsere Bauern und Händler seit Wochen plagt – wurde bei einer Hütte nahe der Weinberge gesehen, die östlich der Abtei und jenseits der Brücke liegt.",
    ["Nothing like a day of boar hunting, eh? Though, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging."] = "Nichts geht über einen Tag Wildschweinjagd, was? Obwohl es hier im Coldridge-Tal so viele Wildschweine gibt, dass es fast den Spaß verdirbt. Man muss sie nicht erst zum Angriff reizen.",
    ["I hate those nasty timber wolves! But I sure like eating wolf steaks... Bring me tough wolf meat and I will exchange it for something you'll find useful."] = "Ich hasse diese fiesen Timberwölfe! Aber Wolfssteaks esse ich furchtbar gern ... Bringt mir zähes Wolfsfleisch, und ich tausche es gegen etwas ein, das Ihr nützlich finden werdet.",
    ["You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."] = "Ihr seht aus, als könntet Ihr etwas gebrauchen, um Eure Hände warm zu halten, hm? Ich sage Euch, was helfen würde: ein Paar schöne, warme Handschuhe.",
    ["Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\" He drove off the beast, but not before it mauled him savagely."] = "Hildelve schrieb in sein Tagebuch, dass er von Mangeclaw angegriffen wurde, einem „riesigen Eisklauenbären“. Er vertrieb das Biest, aber nicht, bevor es ihn übel zugerichtet hatte.",
    ["The Brackwells have a prize-winning pig, Princess. The sow is HUGE, and she got that way from sneaking over here and eating my veggies! So before she comes to our fields...Princess must die!"] = "Die Brackwells haben ein preisgekröntes Schwein, Prinzessin. Die Sau ist RIESIG, und so groß ist sie geworden, weil sie sich hierher schleicht und mein Gemüse frisst! Also, bevor sie auf unsere Felder kommt ... muss Prinzessin sterben!",
    ["I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace. Don't ask me how it got there...it wasn't me!"] = "Ich habe in der Nähe der Fargodeep-Mine gespielt, und ich glaube, ich habe, äh ... ich meine, ich habe die Halskette der alten Dame gesehen. Fragt mich nicht, wie sie dorthin gekommen ist ... ich war es nicht!",
    ["We believe they are hiding out in the Dagger Hills, plotting their next move. Slay the wretches in the name of The People's Militia."] = "Wir glauben, dass sie sich in den Dagger Hills verstecken und ihren nächsten Zug planen. Erschlagt die Elenden im Namen der Volksmiliz.",
    ["Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"] = "Seht nur, was aus diesem Ort geworden ist! Diese Ländereien wurden einst von guten Bauersleuten bewohnt. Aber die verdammten Diebe haben sie alle vertrieben. Mich aber nicht!",
    ["Your previous investigations are proof that the Echo Ridge Mine needs purging. Return to the mine and help clear it of kobolds. Waste no time."] = "Eure bisherigen Nachforschungen beweisen, dass die Echo-Ridge-Mine gesäubert werden muss. Kehrt zur Mine zurück und helft, sie von Kobolden zu befreien. Verliert keine Zeit.",
    ["For your shrewdness and valor, I have a marker here that is good for one piece of armor. I want you to take it to Sara Timberlain at the Eastvale Logging Camp."] = "Für Euren Scharfsinn und Eure Tapferkeit habe ich hier eine Marke, die für ein Rüstungsteil gültig ist. Ich möchte, dass Ihr sie zu Sara Timberlain im Holzfällerlager von Eastvale bringt.",
    ["I must warn you, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home."] = "Ich muss Euch warnen: Diese Angelegenheit muss unter uns bleiben. Die Satyrn sind uns schon peinlich genug, und diese hier ist viel zu nah an unserem Zuhause.",
    ["We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."] = "Wir hörten die Schreie mitten in der Nacht. Und dann, heute Morgen, fehlten tatsächlich zwei Widder aus der Herde. Dieses niederträchtige Biest namens Vagash hat es auf unseren Lebensunterhalt abgesehen.",
    ["I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."] = "Ich bin auf einer Mission, der Mission, das perfekte Starkbier zu brauen. Ich weiß, dass ich es schaffe – Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden ... Die Frostmane-Trolle züchten hoch oben in den Hügeln im Osten eine Pflanze, das Schimmerkraut.",
    ["Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes."] = "Bei näherer Analyse der Lage in Gnomeregan sieht es so aus, als hätten wir die Troggs nicht nur nicht ausgerottet, sondern auch noch den größten Teil des Gnomenvolkes in schreckliche, willenlose, üble Lepragnome verwandelt.",
    ["The Silver Stream Mine to the east ran dry long ago. It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!"] = "Die Silver-Stream-Mine im Osten ist vor langer Zeit versiegt. Die Minenarbeitergilde machte sie zu einem Lagerhaus, aber jetzt haben sich Kobolde dort eingenistet und ihre dreckigen Pfoten an gutes Zwergenwerkzeug gelegt!",
    ["One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power."] = "Eine unserer größten Schwierigkeiten ist es, die natürlichen Ressourcen zu beschaffen, die wir zum Überleben brauchen. Gold war selbst auf dem Höhepunkt der Macht der Allianz knapp.",
    ["Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them."] = "Exekutor Zygand sagt mir, Ihr seid losgezogen und habt Scharlachrote Kreuzfahrer getötet. Die Tirisfal-Lichtungen wimmeln nur so von ihnen.",
    ["The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came."] = "Die Massengräber südwestlich von Garrens Zuflucht im Norden wurden angelegt, um die ... beeindruckende ... Zahl an Toten aufzunehmen, die Tirisfal erlitt, als die Seuche zum ersten Mal ausbrach.",
    ["The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."] = "Das Gebiet um die Agamand-Mühlen ist zu einem Stützpunkt der Geißel geworden. Ihr stärkster Punkt ist die Agamand-Familiengruft, wo ihr örtlicher Militärführer, ein Skelett namens Hauptmann Dargol, sein Hauptquartier errichtet hat.",
    ["Wanted: Maggot Eye! A foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken. This despicable villain has been stealing corpses for use by the Lich King's army."] = "Gesucht: Maggot Eye! Ein abscheuliches Biest, selbst für Gnoll-Verhältnisse. Maggot Eye wurde wegen seiner Verbrechen gegen die Verlassenen zum Tode verurteilt. Dieser verachtenswerte Schurke hat Leichen für die Armee des Lichkönigs gestohlen.",
    ["According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."] = "Laut Berards Tagebuch könnte sich das Moos von den Seeschleichern und Kriechern als nützlich für unser Vorhaben erweisen, eine neue Seuche zu brauen. Diese Bestien leben auf den Inseln im Lordamere-See im Osten.",
    ["As my understanding of Arugal's magic grows so does my disdain for the hapless fool. I am close to completing my research on his so called remedy."] = "Während mein Verständnis von Arugals Magie wächst, wächst auch meine Verachtung für den hilflosen Narren. Ich stehe kurz davor, meine Forschung an seinem sogenannten Heilmittel abzuschließen.",
    ["It's so cold, now. The Plague of Undeath crawls through my veins like an icy serpent. The Mindless State will be upon me soon. But no doomed destiny will prevent me from serving our Dark Lady."] = "Es ist so kalt jetzt. Die Seuche der Untoten kriecht wie eine eisige Schlange durch meine Adern. Der willenlose Zustand wird mich bald ereilen. Aber kein verdammtes Schicksal wird mich davon abhalten, unserer Dunklen Dame zu dienen.",
    ["I now present you with the Water of the Seers. When you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire."] = "Ich überreiche Euch nun das Wasser der Seher. Wenn Ihr bereit seid, trinkt das Wasser nahe dem Stammesfeuer. Sobald Ihr das heilige Wasser zu Euch genommen habt, dauert es einen Augenblick, bis die Vision vor dem Feuer Gestalt annimmt.",
    ["Now that I have the spiders' venom, I'd like some live specimens to study. Unfortunately, capturing a living, giant spider is more than I can ask of you, young."] = "Nun, da ich das Gift der Spinnen habe, hätte ich gern einige lebende Exemplare zum Studieren. Leider kann ich von Euch, Junge, nicht verlangen, eine lebende Riesenspinne einzufangen.",
    ["A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival."] = "Ein Tauren, der sich auf die Jagd versteht, weiß, dass seine Beute nicht bloß eine Trophäe ist. Die Tiere der Ebenen sichern uns das Überleben.",
    ["We are hunters. Down below in Mulgore there is a mighty kodo named Arra'chea."] = "Wir sind Jäger. Unten in Mulgore lebt ein mächtiger Kodo namens Arra'chea.",
    ["The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead."] = "Als Erstes werden wir Euch ein wenig Rückgrat verpassen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber ehrlich gesagt seid Ihr uns lebendig nützlicher als tot.",
    ["Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure! But it remains that I cannot make the trek back to the Den unassisted."] = "Zu sehen, was Ihr für mich getan habt, stärkt mein Herz. Ich darf nicht so leicht fallen! Ich muss durchhalten! Doch bleibt die Tatsache, dass ich den Weg zurück zum Bau nicht ohne Hilfe schaffe.",
    ["Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here."] = "Mächtige Krieger und unbeholfene Neulinge sind gleichermaßen dem giftigen Stachel des Skorpiden erlegen. Ihr werdet große Mengen von Skorpiden nordwestlich von hier finden.",
    ["Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic. It is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven."] = "Durch meine Weissagungen sehe ich, dass sich tief im Brennende-Klinge-Hexenzirkel ein Gegenstand der Macht verbirgt, bewacht von Bestien und schwarzer Magie. Er wird das Medaillon der Brennenden Klinge genannt, und Eure nächste Aufgabe ist es, es zu finden und aus dem Zirkel zu entfernen.",
    ["One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep."] = "Einer meiner aufmerksamsten Späher bringt Nachricht, dass die Wracks von Proudmoores Flotte noch immer vor der Küste von Durotar liegen, östlich der Tiragarde-Festung.",
    ["... your timing is perfect. I just hope I can compliment your haste as well. I was careless while fighting a few of the venomtails nearby, and one of them stung me deeply."] = "... Euer Timing ist perfekt. Ich hoffe nur, dass ich auch Eure Eile loben kann. Ich war unachtsam beim Kampf gegen ein paar der Giftschwänze hier in der Nähe, und einer von ihnen hat mich tief gestochen.",
    ["Lower your voice. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag."] = "Senkt Eure Stimme. Die Kolkar-Zentauren lagern gleich hinter dem Kamm im Westen, in der Kolkar-Klamm.",
    ["The witchdoctor Zalazane dwells on the Echo Isles to the east. They are the isles we once called home. From there he sends his trolls to the mainland, to hex our people and drag more of them under his sway."] = "Der Hexendoktor Zalazane haust auf den Echoinseln im Osten. Es sind die Inseln, die wir einst unsere Heimat nannten. Von dort schickt er seine Trolle aufs Festland, um unser Volk zu verhexen und noch mehr von ihnen unter seine Herrschaft zu zwingen.",
    ["We cannot allow the Burning Blade a foothold in Durotar! We must destroy them before their evil festers!"] = "Wir dürfen der Brennenden Klinge keinen Fuß in Durotar fassen lassen! Wir müssen sie vernichten, bevor ihr Übel zu eitern beginnt!",
    ["please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River."] = "Bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und noch immer nicht zurückgekehrt. Er ging nach Westen ins Brachland, um Krokilisken am Südfurienfluss zu jagen.",
    [". The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock. Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars."] = ". Die Brennende Klinge hat die Höhle östlich von Orgrimmar befallen, die als Schädelfels bekannt ist. In dieser Höhle führen sie abscheuliche Rituale durch und verbrennen ihr eigenes Fleisch mit Sengenden Halsbändern.",
    ["You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff."] = "Ihr habt etwas Vielversprechendes an Euch und werdet Euch vor dem Stamm bewähren. Vielleicht werdet Ihr schon bald in der großen Stadt Donnerfels willkommen geheißen.",
    ["Greetings, young one. You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt. May you bring honor to your clan!"] = "Seid gegrüßt, Junger. Ihr habt ein Funkeln in den Augen; ich sehe, dass Ihr begierig seid, auf die Ebenen zurückzukehren und zu jagen. Möget Ihr Eurem Clan Ehre bringen!",
    ["And again, it is your task to perform the ritual of cleansing. Go to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual."] = "Und wieder ist es Eure Aufgabe, das Reinigungsritual durchzuführen. Geht zum Donnerhorn-Brunnen nördlich des Dorfes und benutzt das Donnerhorn-Reinigungstotem für Euer Ritual.",
    ["According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands."] = "Den Dokumenten zufolge, die Ihr aus der Karawane gerettet habt, schmiedete die Venture Co. viele Pläne, um zu versuchen, uns von unserem Land hier zu vertreiben, damit sie freie Hand hätte, unsere Ländereien zu plündern.",
    ["my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him. I want to ask a favor of you while I finish tanning these leather straps."] = "Mein Bruder steht bald vor Häuptling Bluthuf, und es ist mir eine Ehre, seinen Kopfschmuck für ihn anzufertigen. Ich möchte Euch um einen Gefallen bitten, während ich diese Lederriemen fertig gerbe.",
    ["There are dwarves preparing a dig site to the northwest. They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings."] = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde ruhen, und das stimmt auch, aber das Land auszuhöhlen und zu schänden ist kein Weg, seine Lehren zu erlangen.",
    ["The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion. Perhaps someone in Bloodhoof Village should know of Ghost Howl's demise...."] = "Das zerlumpte Fell von Ghost Howl trägt noch immer eine furchtbare Wunde, die der Wolf in seinen Kämpfen gegen die Brennende Legion erlitten hat. Vielleicht sollte jemand im Dorf Bluthuf von Ghost Howls Ende erfahren ...",
    ["He told me of its demonic red eyes, razor-sharp talons and venomous bite. As fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder."] = "Er erzählte mir von seinen dämonischen roten Augen, den rasiermesserscharfen Klauen und dem giftigen Biss. Wie es das Schicksal wollte, begegnete ich ihm auf meiner Reise durch die Ebenen, und er biss mir böse in die Schulter.",
    ["One of my scouts witnessed an attack on a caravan from Durotar. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout."] = "Einer meiner Späher wurde Zeuge eines Angriffs auf eine Karawane aus Durotar. Die Täter sind tatsächlich der Razormane-Stamm der Stacheleber. Einer der Stacheleber führt die Überfälle an: Kreenig Snarlsnout.",
    ["While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have! As you see, my observatory is ready to go, but it needs the smaller of the two lenses."] = "Ich würde gern alle meine Waren zurückholen, aber ich bin sicher, das ist nicht möglich. Dennoch gibt es ein paar Dinge, die ich unbedingt brauche! Wie Ihr seht, ist mein Observatorium bereit, aber es braucht die kleinere der beiden Linsen.",
    ["The herbs of the Barrens are not quite like herbs in other lands. Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different."] = "Die Kräuter des Brachlands sind nicht ganz wie Kräuter in anderen Ländern. Ihre Eigenschaften sind größtenteils gleich, aber das Wasser der Oase hier verändert die Pflanzen; sie sind nur ein wenig anders.",
    ["The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops. And so, I have a bounty task for you."] = "Die Kolkar sind eine Bedrohung für die Ansprüche der Horde im Brachland; wir müssen die Zahl ihrer Truppen verringern. Und so habe ich eine Kopfgeldaufgabe für Euch.",
    ["Greetings. I am Conservator Ilthalaine. My purpose in Shadowglen is to ensure that the balance of nature is maintained."] = "Seid gegrüßt. Ich bin Bewahrerin Ilthalaine. Mein Auftrag in Schattenglen ist es, dafür zu sorgen, dass das Gleichgewicht der Natur erhalten bleibt.",
    ["Something evil is brewing in the forests of Teldrassil. Look long the hills to where the peaceful furbolgs used to dwell. They have deserted their homes and are amassing under the name of the Gnarlpine tribe."] = "In den Wäldern von Teldrassil braut sich etwas Böses zusammen. Blickt lange die Hügel entlang bis dorthin, wo einst die friedlichen Furbolgs lebten. Sie haben ihre Heimstätten verlassen und sammeln sich unter dem Namen Gnarlpine-Stamm.",
    ["Thinning the younger population of creatures here in Shadowglen was a good start, but there is still work to be done. The resources of the forest will be depleted too quickly if the problem is not addressed."] = "Die jüngere Bevölkerung der Kreaturen hier in Schattenglen auszudünnen war ein guter Anfang, aber es gibt noch Arbeit. Die Ressourcen des Waldes werden zu schnell erschöpft sein, wenn das Problem nicht angegangen wird.",
    ["The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire. I have prepared power stones that when placed near the Seed will disrupt its connection to the Legion."] = "Der Dämonensame ist ein mächtiges Werkzeug der Brennenden Legion. Er ruht in einer Höhle auf dem Düsternebelgipfel, über einem dämonischen Feueraltar. Ich habe Machtsteine vorbereitet, die, wenn man sie in die Nähe des Samens legt, seine Verbindung zur Legion stören werden.",
    ["In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home."] = "In einer Höhle am Südufer des Sees verbreitet ein Holzling namens Oakenscowl Verderbnis unter allen Kreaturen, die den See Al'Ameth ihr Zuhause nennen.",
    ["Now the time has come to save the Druids of the Talon. If we fail now, they will be forever lost in sleep. I shall prepare the Relics of Wakening and perform the ritual."] = "Nun ist die Zeit gekommen, die Druiden der Klaue zu retten. Wenn wir jetzt versagen, sind sie für immer im Schlaf verloren. Ich werde die Relikte des Erwachens vorbereiten und das Ritual durchführen.",
    ["I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade."] = "Ich wurde mit einer kleinen Gruppe Schildwachen hierher entsandt, um den Orakelbaum vor den Harpyien zu schützen, die rund um die Lichtung ihre Nester gebaut haben.",
    ["Small timberlings are sprouting around the waters of Lake Al'Ameth. I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble."] = "Kleine Holzlinge sprießen rund um die Gewässer des Sees Al'Ameth. Ich fürchte, diese Schösslinge sind nicht mehr zu retten – wir sollten versuchen, sie vom Land zu entfernen, bevor sie groß genug werden, um Ärger zu machen.",
    [". A task I would ask of you. Have you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south."] = ". Eine Aufgabe, um die ich Euch bitten möchte. Habt Ihr die Ruinen von Ameth'Aran gesehen? Wenn nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein Stück weiter südlich.",
    ["It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color."] = "Es war das Handwerk eines der mächtigsten Hochgeborenen, das das Siegel erschuf, das mein Gefängnis bildete. In Ameth'Aran, den Ruinen im Süden, die diesen hier gleichen, besteht selbst heute noch eine uralte Flamme, blau an Farbe.",
    ["The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war."] = "Die Kampfeber der Brambleblade-Schlucht im Osten dringen in unsere Stammesjagdgründe vor. Sie werden von den Borstennacken-Stachelebern, mit denen wir im Krieg liegen, zur Bösartigkeit abgerichtet.",
    ["My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need."] = "Zu meinen Pflichten gehört es, unsere verwundeten Krieger zu versorgen, Rüstungen und Kleidung zu schneidern und Schattenpriester Sarvis bei allem zu helfen, was er sonst noch braucht.",
    ["Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."] = "Gesucht: Hogger. Ein riesiger Gnoll, Hogger, treibt sich in den Wäldern im Südwesten von Elwynn herum. Er hat alle Versuche, ihn zu fassen, vereitelt. Die Armee von Sturmwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt.",
    ["I hope you're here to lend us a hand. After the last trogg attack, we could use all the help we can get. I hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception."] = "Ich hoffe, Ihr seid hier, um uns zu helfen. Nach dem letzten Trogg-Angriff können wir jede Hilfe gebrauchen. Ich höre, die Mistkerle tauchen überall im Land auf, und das Coldridge-Tal scheint keine Ausnahme zu sein.",
    ["After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."] = "Nachdem ich diesen Talisman untersucht habe, sehe ich nun, was getan werden muss. Bitte nehmt ihn und tut, worum ich Euch bitte. Ihr sollt die tiefsten Bereiche des Ban'ethil-Hügelgrabbaus erkunden.",
    ["Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."] = "Nun müsst Ihr die Aufgabe vollenden, mit der Ihr betraut wurdet. Nehmt die Spinndrüsen und bringt Lady Sathrahs Opfer Elune dar; lasst die große Spinne ruhen.",
    ["Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."] = "Gnarlpine-Eindringlinge wurden dabei gesehen, wie sie den Ban'ethil-Hügelgrabbau im Westen verwüsten. Die schlummernden Druiden werden für alle Ewigkeit im Smaragdgrünen Traum gefangen sein, ohne von ihrem Schicksal zu wissen, wenn wir nicht helfen.",
    ["- I have heard of you, newcomer. Perhaps it is you that will help us, where others have failed. We tauren have carved a home out of this land, but not without a cost."] = "- Ich habe von Euch gehört, Neuankömmling. Vielleicht seid Ihr es, der uns helfen wird, wo andere versagt haben. Wir Tauren haben uns aus diesem Land eine Heimat geschaffen, aber nicht ohne Preis.",
    ["The antidote is ready. Please see that Iverron drinks it. There is something that you should know -- the antidote -- it will only remain viable for 5 minutes."] = "Das Gegenmittel ist fertig. Bitte sorgt dafür, dass Iverron es trinkt. Da ist etwas, das Ihr wissen solltet – das Gegenmittel – es bleibt nur 5 Minuten lang wirksam.",
    ["You'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine."] = "Ihr findet Bruder Neals in der Abtei, im Glockenturm ... wo er gern seinen Wein verkostet.",
    ["You there! If you're looking for something to make yourself useful, then listen up! We need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment."] = "Ihr da! Wenn Ihr etwas Nützliches tun wollt, dann hört zu! Wir brauchen frisch aus dem Boden gestiegene Rekruten, die nach Totenglocke gehen und nach jeder Art von brauchbarer Ausrüstung suchen.",
    ["You may have killed the raptors, but the silver they stole must be recovered! I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds."] = "Ihr mögt die Raptoren getötet haben, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte, dass die Raptoren südlich von Ratchet eine große Ansammlung von Nestern haben, bekannt als die Raptorengründe.",
    ["You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."] = "Ihr seid einer meiner Leutnants! Bereitet Euch vor. Ich werde Euch bald rufen. Meine Zeit auf der Sengenden Klinge ist nun vielleicht fast vergeudet, aber das bedeutet nicht, dass die Pläne des Schattenrats anderswo darunter leiden müssen.",
    ["Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with..."] = "Viele Bewohner der Legion beschenken ihre Anhänger, wie Ihr wohl wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Dame besser in ihren Händen aufgehoben als in den Händen derer, die ...",
    ["You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs."] = "Ihr findet unter dem Körper des Tauren eine Satteltasche. Er hält sie noch immer fest in seinen Armen, als hätte er versucht, sie während des Angriffs der Troggs zu schützen.",
    ["Mellifluous liquid clear as a baby's tears Turns a lovely deep amber over the years But before we proceed to get lit to the hilt A barrel of charred oak must be built."] = "Süße Flüssigkeit, klar wie Kinderträn', wird über die Jahre ein tiefes Bernstein, schön. Doch ehe wir uns volllaufen lassen, muss ein Fass aus verkohlter Eiche her, so passen.",
    ["Return to your own tribe and let them know of your victory here. Show them your trophy, and bask in the glory..."] = "Kehrt zu Eurem eigenen Stamm zurück und lasst sie von Eurem Sieg hier wissen. Zeigt ihnen Eure Trophäe und sonnt Euch im Ruhm ...",
    ["When my life was ended upon the rocks, I had no clue what the afterlife held for me. The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off."] = "Als mein Leben auf den Felsen endete, hatte ich keine Ahnung, was das Jenseits für mich bereithielt. Der Leuchtturm war in jener Nacht dunkel, weil Old Murk-Eye die Familie des Wärters vertrieben hatte.",
    ["You have proven your loyalty to King Magni. And your hatred for the Dark Iron scum is as great as my own. There is a task I wish to complete myself but I am bound by honor to stay with Longbraid."] = "Ihr habt Eure Loyalität gegenüber König Magni bewiesen. Und Euer Hass auf den Abschaum der Dunkeleisen ist so groß wie meiner. Es gibt eine Aufgabe, die ich selbst erledigen möchte, aber meine Ehre bindet mich an Longbraid.",
    ["I find myself in quite a pinch here. The bottles are close to running dry. The latest booze shipment is long overdue. The orc invasion has been hell."] = "Ich stecke ziemlich in der Klemme. Die Flaschen gehen zur Neige. Die letzte Schnapslieferung ist längst überfällig. Die Orc-Invasion war die Hölle.",
    ["I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."] = "Ich brauche Bauchschuppen von schwarzen Drachenwelpen, um die Schuhe zu bezahlen, die Argus mir aus Goldhain geschickt hat.",
    ["During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor."] = "Während der letzten Orc-Invasion waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen.",
    ["You have uncovered a dark threat to the land. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc."] = "Ihr habt eine dunkle Bedrohung für das Land aufgedeckt. Das Resonit-Fass, das Ihr in jener Höhle gefunden habt, beherbergt einen schlummernden Irdenen namens Goggeroc.",
    ["Targorr the Dread served under Gath'Ilzogg as supreme Executioner. His methods were ruthless, even by filthy orc standards. Men who fought bravely to defend the Kingdom were tortured on his whim."] = "Targorr der Schreckliche diente unter Gath'Ilzogg als oberster Scharfrichter. Seine Methoden waren rücksichtslos, selbst für die Maßstäbe dieser dreckigen Orcs. Männer, die tapfer zur Verteidigung des Königreichs gekämpft hatten, wurden nach seiner Laune gefoltert.",
    ["the gnolls are still out there. I can hear their baying as they hunt in the hills above Lakeshire. And one cry is louder than the rest - Yowler, their leader."] = "die Gnolle sind noch immer da draußen. Ich kann ihr Heulen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und ein Schrei ist lauter als die anderen – Yowler, ihr Anführer.",
    ["our scouts have identified the leader of this recent Trogg incursion. It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug."] = "unsere Späher haben den Anführer dieses jüngsten Trogg-Einfalls ausgemacht. Es scheint, dass diese Bestien in Loch Modan einem Häuptling namens Grawmug folgen.",
    ["By order of the Magistrate of Thelsamar: Chok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary."] = "Auf Anordnung des Magistrats von Thelsamar: Chok'sul, der Oger, der vermutlich der Anführer und Koordinator der Angriffe auf die Stadt Thelsamar, den Steinwerk-Damm und die Ausgrabungsstätte ist, wird tot gesucht – mit allen notwendigen Mitteln.",
    ["The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."] = "Die Dirne! Die Sau! Kenata lebt noch; ihre Familie ist gesund und blüht, während ich leide. Verlassen, in der Tat! Meine Familie ist fort, von der Seuche geholt.",
    ["Many of my friends perished that horrible day when the mine tunnel caved in. If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them."] = "Viele meiner Freunde kamen an jenem schrecklichen Tag ums Leben, als der Minenstollen einstürzte. Falls Euch Eure Abenteuer in jenen Flügel der Mine in Moonbrook führen, haltet bitte die Augen nach Anzeichen offen, die sie identifizieren könnten.",
    ["Edwin VanCleef must be assassinated. While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all."] = "Edwin VanCleef muss ermordet werden. Obwohl es mich betrübt, irgendeinen Mann zum Tode zu verurteilen, ist es zum Wohle der Menschen von Westfall, dass VanCleef ein für alle Mal zur Ruhe gelegt wird.",
    ["Travel to his cottage just north of town, and execute Stalvan, once and for all. When the deed is done, travel to Madame Eva's and show her his family ring."] = "Reist zu seinem Haus nördlich der Stadt und richtet Stalvan ein für alle Mal hin. Wenn die Tat vollbracht ist, reist zu Madame Evas Haus und zeigt ihr seinen Familienring.",
    ["It's no secret that the trademark of the Defias Gang is their Red Bandanas. But we've learned that the material from which these bandanas are made signifies the member's rank."] = "Es ist kein Geheimnis, dass das Markenzeichen der Defias-Bande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass der Stoff, aus dem diese Kopftücher gefertigt sind, den Rang des Mitglieds anzeigt.",
    ["I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!"] = "Ich, der große Bartolo, werde für Euch den weltberühmten, in der ganzen Allianz gerühmten Yeti-Fellumhang anfertigen!",
    ["You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."] = "Ihr kommt gerade noch rechtzeitig! Der Rat von Pyrewood wird jeden Augenblick zurückkehren. Arugal hat im Bergfried anderes zu erledigen. Er benutzt den Rat nur als Marionetten, um die willenlosen Diener von Pyrewood unter seiner Kontrolle zu halten.",
    ["Here you go. Bring this message to Master Carevin. A few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today."] = "Hier, bitte. Bringt diese Nachricht zu Meister Carevin. Noch ein paar von Eurer Sorte, und wir werden die Nachtwache zahlenmäßig übertreffen! Vielleicht könnten wir dann die Arbeit vollenden, die wir wenigen heute fortführen.",
    ["The keg fizzles slightly."] = "Das Fass zischt leicht.",
    ["Just before the invasion I uncovered a large tablet called the Goaz Stone. The translated text breaks off in 4 places. The text speaks of a \"divine plan\" and a \"doomed prophecy.\" I fear we are running out of time."] = "Kurz vor der Invasion entdeckte ich eine große Tafel, den Goaz-Stein. Der übersetzte Text bricht an 4 Stellen ab. Der Text spricht von einem „göttlichen Plan“ und einer „verdammten Prophezeiung“. Ich fürchte, uns läuft die Zeit davon.",
    ["I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind."] = "Ich habe einen Bericht für den König vorbereitet. Ich glaube, Ihr solltet derjenige sein, der ihn ihm überbringt, zusammen mit einem Bericht über Eure Erkenntnisse. Sorgt Euch nicht, er wird Euch zweifellos dafür loben, dass Ihr Eure Pflicht gegenüber dem Volk von Sturmwind erfüllt habt.",
    ["I can't lift the curse from the Eye of Paleth."] = "Ich kann den Fluch nicht vom Auge von Paleth nehmen.",
    ["After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired Paladin with hammer upraised."] = "Nachdem das Fass aus dem Morast gezogen und geöffnet wurde, findet sich darin, in feines Stroh gepackt, eine silbrige Figur. Sie zeigt einen jungen Paladin mit langem Haar und erhobenem Hammer.",
    ["Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery. His time in this land is drawing to an end..."] = "Morbent Fel versteckt sich in seinem Unterschlupf, dem Haus auf dem Hügel im Osten, das auf den Friedhof von Rabenflucht hinabblickt. Seine Zeit in diesem Land neigt sich dem Ende zu ...",
    ["We have a real infestation problem to the west. Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!"] = "Wir haben ein echtes Befallsproblem im Westen. Tunnelratten-Kobolde sind in die Vorgebirge gezogen, errichten Bauten und besudeln unser Land mit ihrem Dreck!",
    ["Ready to go? First, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me."] = "Bereit zum Aufbruch? Zuerst müssen wir dieses Pulver zu Ironband bringen. Für mich allein ist es eine ziemliche Last, und diese Gegenden können gefährlich werden – und wer weiß, was die Dunkeleisen sonst noch für mich auf Lager haben.",
    ["Valdred, once my good friend, was my wife's murderer. Although I am incapable of grieving, I do yearn for revenge. If you kill Valdred and bring me his cursed hands, then I will reward you."] = "Valdred, einst mein guter Freund, war der Mörder meiner Frau. Obwohl ich unfähig bin zu trauern, sehne ich mich nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.",
    ["In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence."] = "In Vorbereitung auf einen Angriff auf Schattenfang wurden zwei Todespirscher zum Bergfried geschickt, um Informationen zu sammeln.",
    ["Sure enough, deep within the Old Jug there is another clue to Sander's treasure."] = "Tatsächlich, tief im Alten Krug befindet sich ein weiterer Hinweis auf Sanders Schatz.",
    ["At last, friends of the Alliance! Help... please... The last thing I remember these foul Orcs overpowered our regiment. Most the men were killed."] = "Endlich, Freunde der Allianz! Helft ... bitte ... Das Letzte, woran ich mich erinnere, ist, dass diese üblen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet.",
    ["An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him."] = "Ein Erzmagier von großer Macht überwacht die Reaktivierung des Leylinienknotens. Bei dem Fortschritt, den sie gemacht haben, besteht unsere einzige Hoffnung, sie aufzuhalten, darin, ihn zu töten.",
    ["Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."] = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab geschaffen haben, gewoben aus den Lehrlingsstäben, die jeder Magier besaß.",
    ["Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle. You must again go to the Isle and destroy Thule Ravenclaw."] = "Jetzt ist die Zeit gekommen, den Stützpunkt der Geißel in Silberwald anzugreifen: die Fenris-Insel. Ihr müsst abermals zur Insel gehen und Thule Ravenclaw vernichten.",
    ["The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."] = "Die Front der Defias verschiebt sich ständig. Ich verfolge ihre Bewegungen schon seit geraumer Zeit. Nebenbei habe ich festgestellt, dass sich viele Mitglieder der Bande an den roten Lederkopftüchern erkennen lassen, die sie tragen.",
    ["The Embalmer is a name told in one of our children's stories. He was a kindly alchemist, driven mad by the death of his wife, Eliza. To restore her, he used dark magic to place his own heart within the bosom of his dead spouse."] = "Der Einbalsamierer ist ein Name aus einer unserer Kindergeschichten. Er war ein gütiger Alchemist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Um sie wiederzubeleben, setzte er mit dunkler Magie sein eigenes Herz in die Brust seiner toten Gattin.",
    ["I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."] = "Ich schickte meinen Lehrling in die Sümpfe, um einige unserer berühmten Riesen-Krokilisken des Sumpflandes zu häuten. Als er nicht zurückkehrte, ging ich los, um nach ihm zu suchen ...",
    ["While you were down there I happened to notice that one of those beasts stood out from the rest. He was bigger and more menacing. I bet he's the one who led the others here to cause the disruption to the dig site."] = "Während Ihr dort unten wart, ist mir aufgefallen, dass eines dieser Biester sich von den anderen abhob. Es war größer und bedrohlicher. Ich wette, es ist dasjenige, das die anderen hierhergeführt hat, um die Grabungsstätte zu stören.",
    ["My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec. But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul."] = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutorin Hadrec Bericht zu erstatten. Aber wir kamen nicht weit – als wir über diese Farm gingen, wurden wir von dem Ghul Ivar dem Üblen angegriffen.",
    ["Dangerous! The following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia: Clerk Horrace Whitesteed."] = "Gefährlich! Die folgenden Menschen aus Hillsbrad wurden als gefährlich eingestuft und von Hochexekutorin Darthalia mit einem Kopfgeld belegt: Schreiber Horrace Whitesteed.",
    ["I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad. So jealous I am..."] = "Ich höre, Ihr wurdet von Darthalia angeworben, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin so neidisch ...",
    ["Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."] = "Oh ... die Blumen blühen in Hillsbrad, und die Luft ist so frisch und belebend. Ich kann nicht anders, als mich im Elend des Ganzen zu suhlen. Ich blicke aus meinem schmutzigen Fenster und sehne den Tag herbei, an dem unsere Neue Seuche dieser Welt den Tod bringt, den sie verdient.",
    ["A mudsnout composite? Absolutely brilliant! Why didn't I think of that? Let me contribute my colloid of decay to this devilish brew."] = "Ein Schlammschnauzen-Verbundstoff? Absolut brillant! Warum bin ich darauf nicht gekommen? Lasst mich mein Kolloid des Verfalls zu diesem teuflischen Gebräu beisteuern.",
    ["High Executor Darthalia sent me to keep watch of Dun Garok from a distance. I had set up camp just out of sight. But when morning came and I had to boil water, I left to gather firewood."] = "Hochexekutorin Darthalia schickte mich, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager knapp außer Sichtweite aufgeschlagen. Doch als der Morgen kam und ich Wasser kochen musste, ging ich los, um Feuerholz zu sammeln.",
    ["Ain't nothin' that irks me more than losin' these here beautiful horses."] = "Nichts ärgert mich mehr, als diese wunderschönen Pferde zu verlieren.",
    ["I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate."] = "Ich bin der neue Magistrat von Süderstade, kürzlich nach der Ermordung des vorherigen Magistrats eingesetzt.",
    ["Take this sealed commendation to Varimathras in the Undercity."] = "Bringt diese versiegelte Belobigung zu Varimathras in die Unterstadt.",
    ["Here is the final challenge that I will put forth. We've been tracking an elusive tiger for weeks."] = "Hier ist die letzte Herausforderung, die ich Euch stellen werde. Wir verfolgen seit Wochen einen schwer fassbaren Tiger.",
    ["You've almost proven yourself to be a master hunter of panthers."] = "Ihr habt Euch fast als Meisterjäger der Panther bewiesen.",
    ["For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."] = "Dafür verwende ich nur die besten Felle alter Krokodile. Sie sind haltbarer und eine bessere Leinwand – wenn Ihr so wollt – für die Muster und Akzente, die Drizzliks Excelsior-Linie ausmachen.",
    ["There is but one final reagent needed to complete the enchantment. In the south, towards the western coast, high above the bluffs, lies a Holy Spring."] = "Es fehlt nur noch ein letztes Reagenz, um die Verzauberung zu vollenden. Im Süden, Richtung Westküste, hoch über den Klippen, liegt eine Heilige Quelle.",
    ["Avast! Who goes there? Argh, I am but useless without me special enchanted eye. Bad enough to have lost me eyes in battle in the first place!"] = "Ahoi! Wer da? Argh, ohne mein verzaubertes Auge bin ich zu nichts nütze. Schlimm genug, dass ich meine Augen überhaupt im Kampf verloren habe!",
    ["Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill."] = "Weil Ihr Euch im Dschungel als solcher Draufgänger erwiesen habt, erzähle ich Euch von einem wilden Raptor, den selbst ich nicht töten konnte.",
    ["So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for."] = "Ihr sucht also einen Altar irgendeiner Art? Nun, ich bin kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt draußen bei jener Insel gehört, die Ihr sucht.",
    ["Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key."] = "Obwohl in diesen Aufzeichnungen keine Erwähnung von Gefreiter Thorsen zu finden ist, verbirgt sich im Einband eines von Herods Hauptbüchern ein kleiner Messingschlüssel.",
    ["While you were gone I fixed the pot you brought me. I even added an extra steam whistle, and look! There's a new chopper at the bottom that'll cut through leg bones!"] = "Während Ihr weg wart, habe ich den Topf repariert, den Ihr mir gebracht habt. Ich habe sogar eine zusätzliche Dampfpfeife angebracht, und seht nur! Unten ist ein neues Hackbeil, der durch Beinknochen schneidet!",
    ["Kurzen may be dead, but...that which drove him to evil still lives! Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn."] = "Kurzen mag tot sein, aber ... das, was ihn zum Bösen trieb, lebt noch! Durch meine Studien habe ich Folgendes herausgefunden: Ein Ogermagier – Mai'Zoth – haust in einem Ogerhügel in den östlichen Bergen von Stranglethorn.",
    ["The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold! Please, you must help me!"] = "Die Venture Company unterhält im ganzen Schlingendorntal eine Reihe von Betrieben, die hart arbeitende Goblins wie mich daran hindern, ehrliches Gold zu verdienen! Bitte, Ihr müsst mir helfen!",
    ["Negolash is a hungry giant. When the giants destroyed our ship, Negolash went straight for my kitchen. He wasn't hungry for crew like the other giants."] = "Negolash ist ein hungriger Riese. Als die Riesen unser Schiff zerstörten, ging Negolash geradewegs zu meiner Küche. Er war nicht hungrig auf Besatzungsmitglieder wie die anderen Riesen.",
    ["Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay. He is exiled from his tribe. Why? Well..."] = "Zanzil der Ausgestoßene lebt mit seinen Anhängern in den Ruinen von Jubuwal und Aboraz, nordöstlich von Beutebucht. Er wurde aus seinem Stamm verbannt. Warum? Nun ...",
    ["We must find if Yenniku is dead. Slay the Bloodscalp Headhunters and take from them their Shrunken Heads. You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them."] = "Wir müssen herausfinden, ob Yenniku tot ist. Erschlagt die Kopfjäger der Blutskalp und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln, und ich werde sie prüfen, um sicherzugehen, dass Yennikus Kopf nicht darunter ist.",
    ["I have reshaped the Mind's Eye into a Soul Gem. Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul."] = "Ich habe das Auge des Geistes in einen Seelenedelstein umgeformt. Sein Zweck ist zweifach: Ihr müsst ihn benutzen, um Yenniku zu betäuben, und sobald er betäubt ist, ihn auf seinen Kopf legen, um seine Seele einzufangen.",
    ["I was sent to Grom'gol to aid Nimboya on his quest, but... I too have reasons for being here. The Bloodscalp tribe is enemy to our tribe. Collecting trophies of our enemies gives us power over them."] = "Ich wurde nach Grom'gol geschickt, um Nimboya bei seiner Aufgabe zu helfen, aber ... auch ich habe meine Gründe, hier zu sein. Der Blutskalp-Stamm ist der Feind unseres Stammes. Trophäen unserer Feinde zu sammeln gibt uns Macht über sie.",
    ["Now that you have gathered Bloodscalp trophies, I have another task for you. The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them."] = "Nun, da Ihr Blutskalp-Trophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Schädelspalter-Stamm der Trolle lebt im Südosten, und seit Jahren führen wir Krieg gegen sie.",
    ["Did Lieutenant Doren want you to report back to him with that patrol information?"] = "Wollte Leutnant Doren, dass Ihr ihm mit diesen Patrouilleninformationen Bericht erstattet?",
    ["To have a chance against Kurzen, we need his healing support neutralized. He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts."] = "Um gegen Kurzen eine Chance zu haben, müssen wir seine heilende Unterstützung ausschalten. Er hat eine große Zahl von Medizinmännern versammelt, die seine Truppen mit Dschungelheilmitteln heilen und unsere Kämpfer mit Giftfarn-Extrakten vergiften.",
    ["Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was. We must not let their valiance go for naught. This crone... Charlga Razorflank..."] = "Der arme Heralath! Und dieser Zwerg ... Lonebrow. Was für eine tapfere Seele er war. Wir dürfen ihre Tapferkeit nicht umsonst gewesen sein lassen. Diese Vettel ... Charlga Razorflank ...",
    ["All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas."] = "Es bleibt nur noch, die Krone des Willens zu Sharlindra in der Unterstadt zu bringen. Sie wird dafür sorgen, dass sie Lady Sylvanas übergeben wird.",
    ["Heavens no! Poor Rustlocke. 'Tis quite a tragedy indeed. We must not let his death pass in vain."] = "Du meine Güte, nein! Der arme Rustlocke. Das ist wahrlich eine Tragödie. Wir dürfen seinen Tod nicht vergeblich sein lassen.",
    ["Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air. The crew tried so hard to save my beautiful Maiden's Folly."] = "Argh, es ist ein furchtbares Leben. Ich sollte jetzt in einem nassen Grab liegen, statt hier am Feuer zu sitzen und frische Luft zu atmen. Die Mannschaft gab sich solche Mühe, meine schöne Maiden's Folly zu retten.",
    ["Such a shame the land is in such shambles. But the Memorial came out quite well!"] = "Eine Schande, dass das Land in solchen Trümmern liegt. Aber das Denkmal ist ganz wunderbar geworden!",
    ["There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers."] = "Ich habe keinen Zweifel, dass innerhalb der Mauern von Stromgarde ein mächtiger Hexenmeister haust. Von Zeit zu Zeit hat dieser Hexenmeister mithilfe eines arkanen magischen Relikts schreckliche Dämonen in großer Zahl herbeigerufen.",
    ["This is bad. It seems the Daggerspines are amassing for an attack. Naga are known for their ruthlessness in battle. They will keep attacking until I am dead."] = "Das ist schlimm. Es scheint, dass sich die Daggerspines für einen Angriff versammeln. Naga sind für ihre Rücksichtslosigkeit im Kampf bekannt. Sie werden so lange angreifen, bis ich tot bin.",
    ["Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"] = "Obwohl mein Wille frei ist, kann ich der Dunklen Dame nicht mehr dienen. Ich spüre, dass meine Zeit auf Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert. Befrager Vishas hat mir das angetan!",
    ["You must defeat Myzrael before she grows in strength. If you do not, then once she has gathered enough power she will challenge her captors!"] = "Ihr müsst Myzrael besiegen, bevor sie an Stärke gewinnt. Wenn nicht, wird sie, sobald sie genug Macht gesammelt hat, ihre Kerkermeister herausfordern!",
    ["A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate. She was last seen within the Syndicate controlled territory of Stromgarde."] = "Auf den Kopf von Marez Cowl, einer hochrangigen Beraterin und Agentin des Syndikats, wurde ein Kopfgeld ausgesetzt. Sie wurde zuletzt im vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.",
    ["Oh my! Oh my! There is a doom approaching. Mark me! A doom! No, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!"] = "Oh weh! Oh weh! Ein Verhängnis nähert sich. Merkt Euch das! Ein Verhängnis! Nein, ich kann nicht davon sprechen ... kann ihre Namen nicht aussprechen, sonst hören sie mich vielleicht! Aber wenn wir mehr über sie erfahren, ja, wenn wir mehr über sie erfahren ... dann können wir vielleicht lernen, wie wir sie vereiteln!",
    ["Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention. I've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use."] = "Vielleicht hilft es Euch sogar, Euch vor dem kommenden Gräuel zu schützen, das Lotwils neueste Erfindung ist. Ich habe mit all den zusätzlichen Steinen gearbeitet, die Ihr für ihn gesammelt habt, und ich kann ein paar schöne Armschienen machen, die Ihr vielleicht benutzen möchtet.",
    ["The last report I received from Agmond is troubling, more so now that he's dead! He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman."] = "Der letzte Bericht, den ich von Agmond erhielt, ist beunruhigend, jetzt, da er tot ist, umso mehr! Er erwähnte, dass seine Gräber an der Ausgrabungsstätte vor Uldaman „uralte Urnen“ freigelegt haben.",
    ["Agmond's tracks lead from the west. It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance."] = "Agmonds Spuren führen aus dem Westen heran. An den blutigen Schmierspuren auf Fels und Sand lässt sich leicht erkennen, dass sich der Zwerg ein ganzes Stück weit dahingeschleppt hat.",
    ["I have the digest for you. I need not tell you to take great care with it. And to keep it far from unfriendly hands. This book holds many truths......And the truth can burn."] = "Ich habe die Zusammenfassung für Euch. Ich brauche Euch nicht zu sagen, dass Ihr sorgsam damit umgehen und sie von unfreundlichen Händen fernhalten sollt. Dieses Buch enthält viele Wahrheiten ... Und die Wahrheit kann brennen.",
    ["After much observation, I have discovered Morganth's plans. He searches for the Scythe of Elune...and he may have found it! If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might."] = "Nach langer Beobachtung habe ich Morganths Pläne entdeckt. Er sucht die Sense von Elune ... und er hat sie vielleicht gefunden! Wenn ja, dann werden das Rotkammgebirge und das Königreich Sturmwind bald seine dunkle Macht zu spüren bekommen.",
    ["You did so well with the lieutenants and underlings that I'd like you to do one last thing for me. Serena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago."] = "Ihr habt Euch bei den Leutnants und Handlangern so gut geschlagen, dass ich Euch um eine letzte Sache bitten möchte. Serena Bloodfeather ist die Schwester einer Harpyie namens Bloodfeather, die vor geraumer Zeit von Rexxar erschlagen wurde.",
    ["The thunderhawk, is a fierce beast. It is time for you to face them. You must find where it roams, and bring me its wings as proof of your successful hunt."] = "Der Donnerfalke ist ein wildes Biest. Es ist an der Zeit, dass Ihr ihm gegenübertretet. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis Eurer erfolgreichen Jagd bringen.",
    ["Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold! Those bastards must be dealt with. Their paranoia has them in a state of frenzy."] = "Schon wieder ging ein Schiff meiner Flotte an diese übereifrigen Menschen auf der Feste Nordwacht verloren! Mit diesen Bastarden muss abgerechnet werden. Ihre Paranoia hat sie in einen Zustand der Raserei versetzt.",
    ["Finally! Someone to rescue me! I can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor."] = "Endlich! Jemand, der mich rettet! Ich kann nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Eiferer aus Theramore sind von Sinnen. Sie haben unser Schiff versenkt und mich gefangen genommen, den einzigen Überlebenden.",
    ["Following Khazgorm's plans it should be no problem to fashion an explosive charge Ah, there we go. Now, I am going to entrust you with a special task."] = "Nach Khazgorms Plänen dürfte es kein Problem sein, eine Sprengladung herzustellen ... Ah, so. Nun werde ich Euch eine besondere Aufgabe anvertrauen.",
    ["Perhaps you know the pain of uncertainty, perhaps not. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters."] = "Vielleicht kennt Ihr den Schmerz der Ungewissheit, vielleicht nicht. Aber wisst dies: Ich stehe hier jeden Tag vom Sonnenaufgang bis zu ihrem Niedergang und suche den Horizont nach mehr dieser Monster ab.",
    ["Attention! A reward is being offered for the death of the murloc \"Murkdeep\"."] = "Achtung! Für den Tod des Murlocs „Murkdeep“ wird eine Belohnung ausgesetzt.",
    ["Take Lok's head to Thork in the Crossroads. He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in such things."] = "Bringt Loks Kopf zu Thork nach Das Kreuz. Er sollte ohne Worte wissen, was mit meinem Stamm geschehen ist – ha, nicht dass er glauben würde, dass Mangletooth bei so etwas half.",
    ["The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons."] = "Die Razormane-Stacheleber im Süden, jenseits des Feldes der Riesen, haben, wie man mir sagt, keine geschickten Schmiede, aber offenbar haben sie begonnen, robustere Waffen zu entwickeln.",
    ["Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose."] = "Wenn man die Frontplatte der Steuerkonsole öffnet, offenbart sich ein dichtes Gewirr aus Kabeln, Röhren und anderen seltsamen mechanischen Gegenständen – von denen die meisten keinen praktischen Zweck zu erfüllen scheinen.",
    ["I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?"] = "Ich nehme an, ich werde es unterwegs lernen ... Kann nicht allzu schwer sein. Hier ein paar Knöpfe, ein oder zwei Hebel ... Nun, seid Ihr bereit zum Aufbruch?",
    ["I have rendered the spores you gave me into an emulsion. I must now send it to my associate, Apothecary Zamah. If you were to carry this to her, she can offer you something from our stores of alchemical goods."] = "Ich habe die Sporen, die Ihr mir gegeben habt, zu einer Emulsion verarbeitet. Ich muss sie nun an meine Kollegin, Apothekerin Zamah, schicken. Wenn Ihr sie ihr bringt, kann sie Euch etwas aus unseren Vorräten an alchemistischen Waren anbieten.",
    ["The raptors of the Barrens are smarter than raptors in other lands. And I think all that smarts is hiding in their horns!"] = "Die Raptoren des Brachlands sind klüger als Raptoren in anderen Ländern. Und ich glaube, all dieser Verstand sitzt in ihren Hörnern!",
    ["Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens. He is fierce, brutal and cunning. Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us."] = "Hezrul Bloodmark ist der Anführer der Kolkar-Zentauren im Brachland. Er ist wild, brutal und gerissen. Ihn zu besiegen würde die Kolkar zersplittern und durcheinanderbringen und ihre Bedrohung für uns stark verringern.",
    ["The grand Isha Awak is lord of these waters. Great is his strength, and solemn his pride. The humans on the coast fear him, for he has consumed many of their number."] = "Der große Isha Awak ist der Herr dieser Gewässer. Groß ist seine Stärke und ernst sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat viele von ihnen verschlungen.",
    ["All right, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there."] = "Na schön, dann eben mit Gewalt. Lasst uns von hier verschwinden, sobald Ihr bereit seid. Wir kämpfen uns bis zur Straße durch – Grimclaw sollte noch dort sein.",
    ["I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave. The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains."] = "Ich entwickle einen Trank, der seltene Pilze braucht, Pilze, die nur in einer bestimmten Höhle wachsen. Die Höhle liegt hinter den Cliffspring-Fällen, im Osten und etwas nördlich am Gebirge entlang.",
    ["In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya."] = "Nach den Schlachten am Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört worden sei und sein Volk tot, einschließlich meiner Liebe, Anaya.",
    ["Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine, a place of great evil in southwestern Ashenvale."] = "Ilkrud Magthrull. Ja, ich kenne ihn. Er ist ein mächtiger Orc-Hexenmeister, der seinen Sitz im Feuernarbenschrein hat, einem Ort großen Übels im Südwesten des Eschentals.",
    ["When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil. While I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost."] = "Als ich den Stein von Relu entdeckte, glaubte ich, er sei der Schlüssel, um das Geheimnis des Fossils zu lüften. Als ich auf der Straße unterwegs war, um Whelgar zu treffen, wurde ich von Raptoren angegriffen, und das Relikt ging verloren.",
    ["So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him."] = "Der Prospektor will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Mir ist nicht wohl dabei, Dunkelküste ohne ihn zu verlassen.",
    ["The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!"] = "Das Pergament, das Ihr an der Glefe des Meisters gefunden habt, ist eine Seite eines uralten Textes ... geschrieben von Elfen!",
    ["I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock. That key is a ring, the Ring of Zoram."] = "Ich fürchte, die Geheimnisse der uralten Statuette bleiben für immer verborgen, es sei denn, Ihr findet den Schlüssel zu ihrem uralten Schloss. Dieser Schlüssel ist ein Ring, der Ring von Zoram.",
    ["Relara's fever has passed, but she is still very weak. I do not believe time alone will give her back the strength she has lost. I believe it will take the power of a moonstone."] = "Relaras Fieber ist abgeklungen, aber sie ist noch immer sehr schwach. Ich glaube nicht, dass die Zeit allein ihr die verlorene Kraft zurückgeben wird. Ich glaube, es wird die Macht eines Mondsteins brauchen.",
    ["Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."] = "Anilia legt ihre Hände auf Eure Schultern und zieht Euch zu sich heran. Keuchend deutet sie auf den Torbogen im Norden, bevor sich ihre Augen schließen und ihr letzter röchelnder Atemzug ihren Körper verlässt.",
    ["Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep. The leader of the Outrunners is an orc named Tharil'zun--we want this orc."] = "Läufer und Renegaten des Schwarzfels legen zwischen hier und der Feste Steinwacht Hinterhalte. Der Anführer der Läufer ist ein Orc namens Tharil'zun – wir wollen diesen Orc.",
    ["Now that I've finished copying the book, here's the original Stresses of Iron. Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay."] = "Jetzt, da ich das Abschreiben des Buches beendet habe, hier ist das Original von Stresses of Iron. Danke für Eure Geduld, und wenn Ihr Milton seht, sagt ihm bitte, dass es mir leidtut, dass es so lange gedauert hat.",
    ["Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."] = "Weil Ihr in der Schlacht von Hillsbrad mit solcher Tapferkeit und Ausdauer gekämpft habt, habe ich diese Belobigung verfasst, die Eure Heldentaten im Kampf preist, damit das Oberkommando sie würdigt.",
    ["Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."] = "Erzmagier Arugal rief die Worgen nach Silberwald, um sich gegen die Geißel zu verteidigen, verlor sofort die Kontrolle über sie und verfiel in Burg Schattenfang unter den Wesen, die er herbeigerufen hatte, dem Wahnsinn.",
    ["Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection. Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to..."] = "Burg Schattenfang birgt ein Buch, das Buch von Ur, das in meiner Sammlung sehr geschätzt würde. Ur war ein großer Magier von Dalaran vor dem Kommen der Geißel, seine Studien anderer Welten sind von großem Wert für ...",
    ["Arugal's own belt. He summoned the worgen to save Silverpine, then lost his mind in Shadowfang Keep surrounded by what he had called."] = "Arugals eigener Gürtel. Er rief die Worgen herbei, um Silberwald zu retten, und verlor dann in Burg Schattenfang den Verstand, umgeben von dem, was er gerufen hatte.",
    ["Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."] = "Arugal haust noch immer in Burg Schattenfang. Wir können Silberwald nicht als strategische Festung für die Dunkle Dame beanspruchen, solange Arugal nicht erschlagen ist. Ich werde dafür sorgen, dass seine Magie ausgelöscht wird.",
    ["These deviate creatures have strange, otherworldly properties."] = "Diese abartigen Kreaturen haben seltsame, fremdartige Eigenschaften.",
    ["Hey. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar. One object of my studies are the insect-like creatures found to the south in the Field of Giants."] = "Hey. Ich wurde zum Kreuz geschickt, um das Land zu beobachten und für meine Herren in Orgrimmar die Geschehnisse festzuhalten. Eines der Objekte meiner Studien sind die insektenartigen Kreaturen, die man im Süden im Feld der Riesen findet.",
    ["The druids in the Wailing Caverns, the Druids of the Fang, are an aberration. They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams."] = "Die Druiden in den Höhlen des Wehklagens, die Druiden der Fangzähne, sind eine Abnormität. Sie gehörten einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch nun trachten sie danach, jenes Land nach ihren eigenen, verdrehten Träumen neu zu formen.",
    ["All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready. Remember, after you've escaped, meet Terenthis back in Auberdine."] = "Also gut ... wenn Ihr sicher seid, schleichen wir uns hier hinaus. Lasst uns aufbrechen, wenn Ihr bereit seid. Denkt daran: Nachdem Ihr entkommen seid, trefft Terenthis wieder in Auberdine.",
    ["So excited I am! Three little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of..."] = "Ich bin ja so aufgeregt! Drei kleine Käfige für drei kleine Elfen! Aber was sollen wir nur mit unseren lieben baumumarmenden Freunden anfangen? Nun, geben wir ihnen einen Vorgeschmack auf ...",
    ["I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones."] = "Ich bin Gerenzo einmal begegnet, aber lasst Euch sagen, er ist kein schöner Anblick. Sein Fleisch sieht aus, als würde es verrotten, und er hat Metall und Zahnräder an seinen Körper gepfropft und einige seiner Gliedmaßen durch mechanische ersetzt.",
    ["The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items. They devised a complex scheme to keep them from falling into the wrong hands."] = "Die Druiden bauten den Krallenbau auf dem Steinkrallengipfel, wo sie viele mächtige Gegenstände aufbewahren. Sie ersannen einen vielschichtigen Plan, damit diese nicht in die falschen Hände fallen.",
    ["I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission. It may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains."] = "Ich bin sicher, Tyrande Wisperwind selbst würde Euch gern dafür danken, dass Ihr an dieser Mission teilgenommen habt. Es mag an der Oberfläche nicht so aussehen, aber was Ihr mit angestoßen habt, könnte sehr wohl unseren Stand im Steinkrallengebirge stärken.",
    ["As you may know, wyverns are often tamed by orcs for use as mounts. But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself."] = "Wie Ihr vielleicht wisst, werden Windreiter oft von Orcs als Reittiere gezähmt. Weniger bekannt ist, dass das Gift eines Windreiters in manchen Kreisen wertvoller ist als das Tier selbst.",
    ["it is now time for you to travel to far-off lands. You are ready. You now hunt Frostmaw, a yeti in the Alterac Mountains. He is elusive, his white coat blending into the snows of his mountain home."] = "es ist nun an der Zeit, dass Ihr in ferne Länder reist. Ihr seid bereit. Ihr jagt nun Frostmaw, einen Yeti im Alterac-Gebirge. Er ist schwer zu fassen, sein weißes Fell verschmilzt mit dem Schnee seiner Bergheimat.",
    ["There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track."] = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das hier zündet. Wenn er den geringsten Fehler macht, kommt er nicht voran, sondern ist nur ein verbrannter Fleck auf der Strecke.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons. But he'll need true indurium ore, not just the flakes."] = "Indurium hat eine erstaunliche Hitzebeständigkeit! Ich bin sicher, es wird für Fizzles Kolben funktionieren. Aber er braucht echtes Induriumerz, nicht nur die Flocken.",
    ["Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it."] = "Mit dem Wasser, das Ihr mitgebracht habt, werdet Ihr die Flamme, die das Zentaurenrelikt festhält, vorübergehend löschen können. Es wirkt jedoch nicht dauerhaft, also müsst Ihr schnell sein.",
    ["As you might know, I collect lore. Old lore. Powerful lore. Lore that opens doorways, and lore that can awaken Those Who Sleep."] = "Wie Ihr vielleicht wisst, sammle ich Wissen. Altes Wissen. Mächtiges Wissen. Wissen, das Türen öffnet, und Wissen, das Jene, Die Schlafen, erwecken kann.",
    ["The fight goes well. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings."] = "Der Kampf verläuft gut. Vielleicht erlaubt uns der Kriegshäuptling, in unsere Heimat zurückzukehren, bevor die Jahreszeiten wechseln, wenn wir weiterhin solch große Fortschritte in unserem Kampf gegen die Dämonen und ihre Untergebenen machen.",
    ["At last, help has arrived! You have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place."] = "Endlich ist Hilfe eingetroffen! Ihr habt keine Ahnung, wie lange ich hier schon gefangen gehalten werde. Ich kann mich nicht erinnern, wann ich zuletzt das Äußere dieses Ortes gesehen habe.",
    ["I have not long to live... so... so... weak....the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel... But before I... d-d-die......my wife, Treshala..."] = "Ich habe nicht lange zu leben ... also ... also ... so schwach ... der t-t-tapfere Zwerg, Lonebrow, wurde geschickt, um F-F-Falfindel zu w-w-warnen ... Aber bevor ich ... s-s-sterbe ... meine Frau, Treshala ...",
    ["you helped us against the Magram. Now, help us beat the Maraudine! Kill the head of their clan, Khan Hratha! To face him, blow the Maraudine War Horn."] = "Ihr habt uns gegen die Magram geholfen. Nun helft uns, die Maraudine zu schlagen! Tötet das Oberhaupt ihres Clans, Khan Hratha! Um ihm gegenüberzutreten, blast das Maraudine-Kriegshorn.",
    ["Now that you scared the centaur clans, it's time to bleed them. When traveling Desolace, hunt centaur. I don't care which clan you hunt. Just gather ears."] = "Nun, da Ihr die Zentaurenclans erschreckt habt, ist es an der Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Es ist mir egal, welchen Clan Ihr jagt. Sammelt nur Ohren.",
    ["The Gelkis Khan is dead, and now the Maraudine will fall! Kill the Maraudine Khan, Hratha! To face him, blow the horn on the high bluff in the Valley of Spears."] = "Der Gelkis-Khan ist tot, und nun werden die Maraudine fallen! Tötet den Maraudine-Khan, Hratha! Um ihm gegenüberzutreten, blast das Horn auf der hohen Klippe im Tal der Speere.",
    ["Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done. Haha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time."] = "Bringt Karnitols Sachen zu Roetten nach Eisenschmiede, und er wird Euch für gute Arbeit bezahlen. Haha, wenn Ihr nicht aufpasst, ist er so zufrieden mit Euch, dass er Euch bittet, ganz bei uns einzusteigen.",
    ["To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway."] = "Um bezahlt zu werden, müsst Ihr zurück nach Eisenschmiede und mit Roetten selbst sprechen. Er wird sich sowieso freuen, Leftwitchs Paket los zu sein.",
    ["Serra'kis is the great water beast the naga breed in the flooded halls of Blackfathom Deeps, and the reason the lower temple is under water at all."] = "Serra'kis ist das große Wasserungeheuer, das die Naga in den überfluteten Hallen der Tiefschwarzen Grotte züchten, und der Grund, warum der untere Tempel überhaupt unter Wasser steht.",
    ["Ghamoo-ra is the ancient turtle the naga keep in Blackfathom Deeps -- old enough that the Twilight cultists there treat it as part of the temple."] = "Ghamoo-ra ist die uralte Schildkröte, die die Naga in der Tiefschwarzen Grotte halten – so alt, dass die Zwielichtkultisten dort sie wie einen Teil des Tempels behandeln.",
    ["Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world."] = "Gestärkt durch die uralten Riten der chaotischen Alten Götter, trachten die Mitglieder des Zwielichthammers danach, die Rückkehr ihrer dunklen Gönner herbeizuführen und Tod und Schrecken über die Welt zu verbreiten.",
    ["Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor? I fear that the blood elves will meet a similar deformation."] = "Törichte Blutelfen, die mit dämonischer Magie hantieren. Haben sie nicht gesehen, was mit den Naga und den Satyrn von Kalimdor geschah? Ich fürchte, den Blutelfen wird eine ähnliche Entstellung widerfahren.",
    ["Now there is just one more item needed to complete this device. Cog's blueprint calls for a lens of some sort. The only lens I know of that would be large enough will be very difficult to acquire."] = "Nun fehlt nur noch ein Gegenstand, um dieses Gerät zu vervollständigen. Cogs Bauplan verlangt eine Art Linse. Die einzige Linse, die mir bekannt ist und groß genug wäre, wird sehr schwer zu beschaffen sein.",
    ["The Scarlet Crusade's chief scholar, who guards the Monastery library and its collection rather more aggressively than a librarian should."] = "Der oberste Gelehrte des Scharlachroten Kreuzzugs, der die Bibliothek des Klosters und ihre Sammlung weit aggressiver bewacht, als ein Bibliothekar es sollte.",
    ["The survival of our people and lands comes at unfortunate costs. You have spilled the blood of nature's servants; many sick animals you have felled."] = "Das Überleben unseres Volkes und unserer Länder fordert bedauerliche Opfer. Ihr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr niedergestreckt.",
    ["The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea. But perhaps, by studying the past, we can know what to expect and be better prepared for the unknown."] = "Die Zukunft ist unausweichlich! Wir stürzen uns auf sie zu wie fallende Regentropfen auf das Große Meer. Doch vielleicht können wir durch das Studium der Vergangenheit wissen, was uns erwartet, und besser auf das Unbekannte vorbereitet sein.",
    ["The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?"] = "Der Irdene Ring hegte lautere Absichten gegenüber unseren verseuchten Brüdern. Aber wer kann die Beweggründe jener kennen, die dem Ältestenrat ins Ohr flüstern?",
    ["Revelosh was a Shadowforge explorer who went into Uldaman looking for the origin of the dwarves, and became part of the ruin instead."] = "Revelosh war ein Forscher der Schattenschmiede, der nach Uldaman ging, um den Ursprung der Zwerge zu finden, und stattdessen Teil der Ruine wurde.",
    ["A Gnomeregan oddity whose Use effect grants a huge burst of attack speed. Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision."] = "Eine Kuriosität aus Gnomeregan, deren Anwendungseffekt einen gewaltigen Schub an Angriffsgeschwindigkeit gewährt. Wilde Druiden behielten sie allein deshalb, weil sie in Katzengestalt funktioniert – und sie hat nur begrenzte Aufladungen, sodass jede Benutzung eine Entscheidung ist.",
    ["Mud big ogre. Me hungry. Go bash fishy. Bring Mud food. You feed Mud or Mud eat you."] = "Mud großer Oger. Mud hungrig. Geht hauen Fischi. Bringt Mud Essen. Ihr füttert Mud oder Mud isst Euch.",
    ["The head of the beast is ready to be taken off... with great force. You have shown every sign that you are able to help us with this final mighty blow."] = "Der Kopf des Biests ist bereit, abgetrennt zu werden ... mit großer Wucht. Ihr habt jedes Anzeichen gezeigt, dass Ihr uns bei diesem letzten gewaltigen Schlag helfen könnt.",
    ["Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep. And not only was it pretty--it held great power for those with the knowledge to use it."] = "Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, das Diadem der Tiefe. Und es war nicht nur hübsch – es hielt große Macht für jene bereit, die das Wissen hatten, es zu benutzen.",
    ["Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"] = "Feldwebel Bly hat mich bestohlen! Er sagte, er würde es sich nur ausleihen, aber er hat meinen geliebten Divino-Matic-Stab gestohlen!! Ohne diesen Stab, wie soll ich wissen, wo ich neue Wasserlöcher graben muss??",
    ["Wha.. What happened? The last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs."] = "Wa... Was ist passiert? Das Letzte, woran ich mich erinnere, ist, dass ich von einer Gruppe Dunkeleisenzwerge gefangen genommen, bis an den Rand des Todes geprügelt und dann hier zu diesen dreckigen Troggs geworfen wurde.",
    ["Listen, that ring is yours, sure..."] = "Hört zu, dieser Ring gehört Euch, sicher ...",
    ["No, no, no - I'm not all of the sudden saying that the ring is mine."] = "Nein, nein, nein – ich sage nicht plötzlich, dass der Ring mir gehört.",
    ["When we fled Gnomeregan, we left so much data behind! Vitally important data! I need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan."] = "Als wir aus Gnomeregan flohen, ließen wir so viele Daten zurück! Lebenswichtige Daten! Ich brauche die Daten auf einer prismatischen Lochkarte von einem Hochsicherheits-Terminal Matrix-Punchograph 3005-D tief in Gnomeregan.",
    ["It's terrible. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh. What we need are spare parts."] = "Es ist schrecklich. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrodrillmatischen Ausgrabungsmaschinen nach Dun Morogh zu bringen. Was wir brauchen, sind Ersatzteile.",
    ["I have cutting to do. I can't tell you what I'm going to cut, but... I need myself a blade. A certain blade... Some people call it a sword. I call it a swing blade."] = "Ich habe etwas zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber ... ich brauche eine Klinge. Eine bestimmte Klinge ... Manche nennen es ein Schwert. Ich nenne es eine Schwingklinge.",
    ["Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."] = "Gnomentechnologie – vor zwei Jahren war ihre häufigste Verwendung noch die Pointe eines Witzes. Die Zeiten haben sich sicherlich geändert. Jetzt haben sie ein neues Gefährt gebaut, das besser ist als alle unsere Schredder-Modelle zusammen.",
    ["My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!"] = "Meine Philosophie zur Lederverarbeitung ist, dass die Arbeit von bestmöglicher Qualität sein muss – keine Kompromisse. Jeder, der sagt, dass Qualität keine Rolle spielt, will Euch Grundstücke am Meer in Dun Morogh verkaufen!",
    ["I take pride in my leather work, and I feel it shows; quality should never be compromised. Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!"] = "Ich bin stolz auf meine Lederarbeit, und ich finde, man sieht es; an der Qualität sollte man nie Abstriche machen. Jeder, der sagt, dass Qualität keine Rolle spielt, würde Euch auch glauben machen, dass die Erde keine Geheimnisse bewahrt!",
    ["\"Here you go, the power source is safely removed and the data is preserved. Well, safe journeys and all that."] = "„Bitte sehr, die Energiequelle ist sicher entfernt und die Daten sind gesichert. Nun, gute Reise und so weiter.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure."] = "Die Stimme des Gnoms knistert erneut aus dem Roboter: „Ich muss OOX-17/TN an einen offenen, sicheren Ort bringen, damit er ein langwieriges Startverfahren einleiten kann.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."] = "Die Stimme des Gnoms knistert erneut aus dem Roboter: „Ich muss OOX-22/FE an einen offenen, sicheren Ort bringen, damit er ein langwieriges Startverfahren einleiten kann.",
    ["We must save Sharpbeak! Fight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!"] = "Wir müssen Sharpbeak retten! Kämpft Euch an die Spitze von Jintha'Alor im Herzen des Gebiets der Vilebranch, besorgt Euch den Schlüssel zu Sharpbeaks Käfig von der üblen Priesterin Hexx und findet und rettet dann Sharpbeak!",
    ["Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then."] = "Glaubt Ihr, Ihr könntet mir helfen, den Weg zurück zu meinem Freund Rockbiter zu finden? Er sollte auf mich aufpassen ... Aber ich neige dazu, hin und wieder davonzuwandern.",
    ["I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff!"] = "Ich bin gerade erst in Feralas angekommen, und ich habe gehört, dass die Gordunni-Oger, die hier in der Wildnis hausen, interessante Mineralien haben. Wer weiß, was sie vorhaben, aber sie beschützen das Zeug jedenfalls ordentlich!",
    ["Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you."] = "Bevor Ihr ruht, sprecht noch einmal mit Tok'Kar. Während Ihr weg wart, hat er, glaube ich, ein paar Waffen fertiggestellt. Für Eure Hilfe hier würde er Euch eine davon anbieten.",
    ["There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers."] = "Bei meinen Kunden ist der saftige Geschmack von Krabblerfleisch sehr gefragt; besonders das Fleisch der monströsen Krabbler.",
    ["Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin."] = "Das Muisek in die Waffen einzuprägen ist ein schwieriger Vorgang. Jetzt, da ich alle erforderlichen Materialien und das Muisek der Kreaturen habe, die Ihr gefangen habt, kann ich beginnen.",
    ["So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family."] = "Also, die Zeit ist jetzt gekommen? Ich schätze Eure Mühen, und falls die Lage es nicht zulässt, dann erlaubt mir, Euch schon jetzt für alles zu danken, was Ihr für mich und meine Familie getan habt.",
    ["Black dragons kill many ogre. Kill Tharg's wife."] = "Schwarze Drachen töten viele Oger. Töten Tharg Frau.",
    ["For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered."] = "Für all die Arbeit, die Ihr geleistet habt, verdient Ihr eine gute Belohnung. Kehrt zu Delgren zurück und sagt ihm, dass Athrikus Narassin durch Eure Hand ruht und der Kult des Dunklen Strangs geschlagen und zerstreut ist.",
    ["A while ago, I had an incident with the Shadowforge Dwarves. They brought me to Angor Fortress to study two types of strange stones from Uldaman."] = "Vor einer Weile hatte ich einen Zwischenfall mit den Schattenschmiede-Zwergen. Sie brachten mich zur Festung Angor, um zwei Arten seltsamer Steine aus Uldaman zu untersuchen.",
    ["The Druids of the Fang broke from Cenarius and let the Emerald Nightmare into the Wailing Caverns. These were theirs."] = "Die Druiden der Fangzähne brachen mit Cenarius und ließen den Smaragdgrünen Albtraum in die Höhlen des Wehklagens. Diese hier gehörten ihnen.",
    ["The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade."] = "Die Spinnen der Sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Handwerkern unseres Gewerbes sehr begehrt.",
    ["They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price. It gets worse."] = "Sie nennen sich der Untermarkt: Halsabschneiderische Händler, die verkaufen, schieben, tauschen und für den richtigen Preis so ziemlich alles tun. Es kommt noch schlimmer.",
    ["A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor. He would be very interested in a sample of the wolf hearts Renferrel sent me."] = "Ein Kollege in Kalimdor, Apotheker Helbrim, erforscht die Wirkung von Lordaeron-Giften auf die Tiere Kalimdors. Er wäre sehr an einer Probe der Wolfsherzen interessiert, die Renferrel mir geschickt hat.",
    ["This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak. She'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here."] = "Diese Schriftrolle stammt von jener ränkeschmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel. Sie wird mit dem Boten, dem Ihr dies abgenommen habt, keinen Kontakt mehr aufnehmen, heh, aber wir müssen hier unsere Stellung halten.",
    ["This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare."] = "Diese Scherbe birgt große Geheimnisse; sie ist die reine Essenz des Smaragdgrünen Traums. Was ich jedoch in dieser Scherbe sehe, ist kein Traum; man würde diese Art Vision einen Albtraum nennen.",
    ["Please, take from this a relic of old. We no longer have a use for the item. May it serve you well in your fight against the legion."] = "Bitte, nehmt hieraus ein Relikt aus alter Zeit. Wir haben keine Verwendung mehr für den Gegenstand. Möge er Euch in Eurem Kampf gegen die Legion gute Dienste leisten.",
    ["the creation of each weapon will take some time. Additionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration."] = "die Herstellung jeder Waffe wird einige Zeit dauern. Außerdem könnt Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten einsetzen. Seine schwächende Wirkung gegen Razelikh den Schänder und seine Diener kann in der Dauer schwanken.",
    ["Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch. Make haste to Wyrmbog in the south of Dustwallow Marsh."] = "Onyxias Brut wurde über das Drachentrübe verstreut. Es ist unerlässlich, dass keine weiteren Welpen schlüpfen dürfen. Eilt zum Wyrmbog im Süden der Düstermarschen.",
    ["Big dragons come and make fire at old home. Me smart ogre."] = "Große Drachen kommen und machen Feuer an alte Heimat. Ich kluger Oger.",
    ["Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring."] = "Hier draußen in der Wildnis haben Kindal und ich nur bescheidene Mittel, um Eure Hilfe zu belohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring.",
    ["Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward."] = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, Ihr sprecht ihn darauf an, wenn Ihr nach Eisenschmiede zurückkehrt. Ich bin sicher, er wird noch immer an seinem Platz im Mystischen Viertel sein.",
    ["Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly. Ah, this is indeed a good day. Thank you for your help."] = "Kehrt zu Belgrom in Orgrimmar zurück. Er wird ihren Kopf selbst sehen wollen! Wir werden bald dorthin zurückkehren. Ah, das ist wahrlich ein guter Tag. Danke für Eure Hilfe.",
    ["It... It... It was all a trap. Forgive... me. Kill the bastard... Kill him for us... for Thorius."] = "Es ... Es ... Es war alles eine Falle. Verzeiht ... mir. Tötet den Bastard ... Tötet ihn für uns ... für Thorius.",
    ["Will you assist me, mortal? Will you find the prayer to Elune? As I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person."] = "Werdet Ihr mir helfen, Sterblicher? Werdet Ihr das Gebet an Elune finden? Wie ich sagte, war das Gebet in eine goldene Tafel geritzt. Einer dieser götzenanbetenden Schurken muss es bei sich tragen.",
    ["Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep. But I had never been to the Blasted Lands before!"] = "Meister Mazens Anweisungen waren ziemlich klar: Einen sehr wichtigen Aufsatz an Wächter Mahar Ba in der Feste Nethergarde liefern. Aber ich war noch nie in den Verwüsteten Landen gewesen!",
    ["Now it is time to capture the essence of the avatar of Hakkar. Take the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth."] = "Nun ist es an der Zeit, die Essenz des Avatars von Hakkar einzufangen. Bringt das Ei von Hakkar zum Heiligtum des Gefallenen Gottes im Versunkenen Tempel in Azeroth.",
    ["Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain."] = "Razelikhs Unterschlupf liegt auf dem höchsten Berg in den Verwüsteten Landen. Der einzige Weg zum Unterschlupf führt über die Teleportrunen nahe dem Berg.",
    ["My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies. Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life."] = "Meine Clanschwester Mura Runetotem reiste nach Silberwald, um unseren untoten Verbündeten zu helfen. Silberwald ist ein kranker Wald, ein sterbender Wald, und es war Muras Hoffnung, ihm neues Leben zu bringen.",
    ["In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious..."] = "Im Brachland liegt ein grässliches Gewirr verschlungener Ranken, genannt Die Hügel der Klingenhauer. Während unsere ersten Beobachtungen dieses Ortes wenig Bedrohung zeigten, sind unsere jüngsten Erkenntnisse weit ernster ...",
    ["I'm a scientist, but also a treasure hunter at heart! Long ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity."] = "Ich bin Wissenschaftler, aber im Herzen auch ein Schatzjäger! Vor langer Zeit, als Trolle dieses Land bewohnten, schufen sie große Mengen an Zierrat nach dem Vorbild von Gahz'rilla, einer Hydra, die sie als Gottheit verehrten.",
    ["A like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long. Tell you what, I'll fix you up a nice stew. Just need a few dig rats."] = "Einer wie Ihr muss hier im Brachland ziemlich hungrig werden. Ich selbst verhungere den ganzen Tag. Wisst Ihr was, ich koche Euch einen schönen Eintopf. Ich brauche nur ein paar Grabratten.",
    ["It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor."] = "Es ist offensichtlich geworden, dass wir nicht gewährleisten können, dass Blacklash und Hematus in Lethlor eingesperrt bleiben.",
    ["I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead."] = "Ich diente einst dem Scharlachroten Kreuzzug mit Ehre, Loyalität und Stolz. Ich glaubte, seine Sache sei eine edle: Azeroth von den Untoten zu befreien.",
    ["I used to sail a ship from here all the way to Ratchet, in Kalimdor. I was a successful captain with a sterling reputation. Until... Those cursed sea giants ruined me!"] = "Ich segelte früher von hier aus ein Schiff bis nach Ratchet in Kalimdor. Ich war ein erfolgreicher Kapitän mit tadellosem Ruf. Bis ... Diese verfluchten Seeriesen haben mich ruiniert!",
    ["I think I can fix the samophlange, but I'm going to need the user's manual first."] = "Ich glaube, ich kann den Samophlansch reparieren, aber ich brauche erst die Bedienungsanleitung.",
    ["General Shandris Feathermoon would like to speak with you personally."] = "General Shandris Mondfeder möchte persönlich mit Euch sprechen.",
    ["What?! Ah, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it? You did the work, so I suppose it is only right you reap the greatest reward from it."] = "Was?! Ah, ich habe also ein Kopfgeld erwähnt, nicht wahr? Nun, das wird mir eine Lehre sein, den Mund aufzumachen, was? Ihr habt die Arbeit getan, also ist es wohl nur recht, dass Ihr die größte Belohnung davon erntet.",
    ["In Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death."] = "Im Krater von Un'Goro gibt's Raptoren mit tödlichen Klauen. Manche dieser Raptoren haben manchmal weiße Klauen statt schwarzer wie der Tod.",
    ["My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."] = "Mein Bruder Ribbly war schon immer eine Last für seine Familie, nahm unser Geld und verschwendete es für einen Plan nach dem anderen.",
    ["My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger."] = "Mein körperliches Wesen stellte nach einer Stunde dieser Folter seine Funktion ein. Das Biest riss mir dann meinen Hochzeits-Nasenring vom Gesicht und steckte ihn sich auf den Finger.",
    ["your help has been immeasurable. The time will come, no doubt, when I'll ask for your assistance against the silithid once more."] = "Eure Hilfe war unermesslich. Es wird zweifellos die Zeit kommen, da ich Euch abermals um Beistand gegen die Silithiden bitten werde.",
    ["Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos... The skull of Gul'dan ensured that none were spared here."] = "Teufelswald war einst ein friedliches und stilles Land ... Bis die Legion Fuß fasste. Die Höllenbestien, die Zerstörung, das Chaos ... Der Schädel von Gul'dan sorgte dafür, dass hier niemand verschont blieb.",
    ["A second encampment of satyrs threatens the land of Felwood towards the north, led by the cruel Xavaric. The vile betrayers and tricksters feed upon the corruption of the native creatures of Felwood."] = "Ein zweites Lager von Satyrn bedroht das Land des Teufelswalds im Norden, angeführt vom grausamen Xavaric. Die üblen Verräter und Betrüger nähren sich von der Verderbnis der einheimischen Kreaturen des Teufelswalds.",
    ["This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains."] = "Dies wird der schwierigste Teil sein, denn der Plan hat gewisse Tücken. Nördlich von hier findet Ihr einen kleinen Pfad in die Berge.",
    ["Let me to be frank with you. I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain."] = "Lasst mich offen mit Euch sprechen. Mich interessiert – nein, beunruhigt – warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie die Mittel des Zirkels benutzt, um riesige Mengen Morgenkorn zu beschaffen.",
    ["I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step. But I am no longer the hero..."] = "Ich erinnere mich endlich ... Ich kam tatsächlich hierher, um gegen Blazerunner zu kämpfen. Ich war auf einer Reise, und dies sollte der letzte Schritt sein. Aber ich bin nicht mehr der Held ...",
    ["You'd think that being chief digger for Marshal Expeditions means I like digging. There might be worse things to do in this world... but none really leap to mind."] = "Man könnte meinen, dass ich als Chefgräber der Marshal-Expeditionen gern grabe. Es gibt vielleicht Schlimmeres auf dieser Welt ... aber mir fällt so recht nichts ein.",
    ["Ugh... It's so hot... I was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion."] = "Uff ... Es ist so heiß ... Ich habe dieses Gebiet erkundet, als die Hitze plötzlich unerträglich wurde. Ich muss unter einem Hitzschlag leiden.",
    ["I'm making a flying machine! I got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death."] = "Ich baue eine Flugmaschine! Ich bin hier gestrandet und furchtbar schlecht darin, mich zurechtzufinden. Ich würde einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Biester machen mir Todesangst.",
    ["The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."] = "Die Dunkeleisenzwerge, angeführt vom Schurken Hurley Blackbreath, haben eines der besten Rezepte der Donnerbräus gestohlen, das Donnerbräu-Lagerbier. Diese Schurken! Sie verdienen ein so edles Gebräu nicht! Ich habe eine schwere Aufgabe für Euch.",
    ["Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."] = "Bolvar ist ein Narr. Ich sammelte seinen kostbaren „Beweis“, um ihn ihm in den Rachen zu stopfen. Er ist ein blinder Possenreißer. Der Beweis steht zwei Fuß von ihm entfernt, und er sieht ihn nicht.",
    ["We need to get out of here. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell."] = "Wir müssen hier raus. Helft mir, meine Ausrüstung aus dem Vorratsbereich zurückzuholen und meine Freunde zu befreien. Wenn wir es hier heraus schaffen, sollt Ihr zu Morgans Wacht gehen und mit Marschall Maxwell sprechen.",
    ["As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."] = "Als wäre der Absturz in den See nicht schlimm genug gewesen, haben mich Troggs von der nahen Insel angegriffen und mein Werkzeug und meinen besonderen Blastenheimer-Blastencapper-Sprengstoff gestohlen.",
    ["I look at my undeath as a malady. An illness that merely requires treatment; however, it is also a great blessing for the Argent Dawn. What better vessel to smite the heathens of the Scourge than through the undead?"] = "Ich betrachte mein Untotsein als Leiden. Als Krankheit, die lediglich behandelt werden muss; es ist jedoch auch ein großer Segen für die Argentumdämmerung. Welches bessere Gefäß gibt es, um die Heiden der Geißel niederzustrecken, als die Untoten?",
    ["I draw my power - my will to continue living and breathing - from the unmitigated hatred I have for the Scourge and all that they have done."] = "Ich schöpfe meine Kraft – meinen Willen, weiterzuleben und zu atmen – aus dem ungebremsten Hass, den ich auf die Geißel und alles, was sie getan hat, empfinde.",
    ["Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."] = "Bringt diesen Brief zurück nach Sturmwind und lasst Malin wissen, dass Kryten und ich bald zu Hause sein werden. Er wird Euch gut dafür belohnen, dass Ihr uns hier geholfen habt, daran habe ich keinen Zweifel.",
    ["We've learned that a source of furbolg corruption is from the satyr. They hold sway via talismans that they channel magic through. If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!"] = "Wir haben erfahren, dass eine Quelle der Furbolg-Verderbnis von den Satyrn stammt. Sie haben ihren Einfluss durch Talismane, durch die sie Magie leiten. Wenn die Furbolgs eine Chance auf Rettung haben sollen, müssen wir den Satyr-Verderber herauslocken und diesen Talisman an uns bringen!",
    ["I was on my way to Maestra's Post to meet Liladris Moonriver, but I decided to stop here and take a short nap. Ever since I awoke from the emerald dream, I have been so sleepy..."] = "Ich war auf dem Weg zu Maestras Posten, um Liladris Moonriver zu treffen, aber ich beschloss, hier anzuhalten und ein kurzes Nickerchen zu machen. Seit ich aus dem Smaragdgrünen Traum erwacht bin, bin ich so schläfrig ...",
    ["The moonwell water has revealed that embedded inside the crystal are a few small fragments of bone, as well as half of a jawbone."] = "Das Mondbrunnenwasser hat enthüllt, dass im Kristall ein paar kleine Knochenfragmente sowie eine halbe Kieferknochen eingebettet sind.",
    ["That beached creature is not an isolated incident here in Darkshore. There are more along the coastline and even in the water."] = "Diese gestrandete Kreatur ist kein Einzelfall hier an der Dunkelküste. Es gibt weitere entlang der Küste und sogar im Wasser.",
    ["I love crab. Crabs are the fruit of the sea! You can bake it, barbecue it, boil it, and broil it. They're pan fried, deep fried, and stir fried."] = "Ich liebe Krabben. Krabben sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Sie werden gebraten, frittiert und gewokt.",
    ["I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her."] = "Ich habe Kinelory nach einer Nacht in der Taverne schon viel schlimmer aussehen sehen als jetzt. Ihr habt sie offensichtlich gut beschützt.",
    ["you have served us well in the past, so I now entrust to you an important mission. The Grimtotem Clan is up to something secretive. Three agents of unknown origin were seen visiting the Grimtotem over the recent weeks."] = "Ihr habt uns in der Vergangenheit gut gedient, daher vertraue ich Euch nun eine wichtige Mission an. Der Grimmtotem-Clan führt etwas Geheimes im Schilde. In den vergangenen Wochen wurden drei Agenten unbekannter Herkunft dabei gesehen, wie sie die Grimmtotem besuchten.",
    ["But, there may be more centaur than I thought, I ask you, to fight with me against these vile assassins."] = "Aber es könnten mehr Zentauren sein, als ich dachte. Ich bitte Euch, mit mir gegen diese üblen Meuchelmörder zu kämpfen.",
    ["Take this refined and purified Incendia powder to Thousand Needles and toss it on the sacred fire of life. It is located in the Darkcloud Pinnacle on an isolated needle where they bury their dead."] = "Bringt dieses raffinierte und gereinigte Incendia-Pulver nach Tausend Nadeln und werft es in das heilige Feuer des Lebens. Es befindet sich auf dem Dunkelwolkengipfel auf einer abgelegenen Nadel, wo sie ihre Toten begraben.",
    ["Arnak thinks we're going to be married... but after I declined his offer he came back that night and kidnapped me. My brother tried to stop him, but Arnak was too strong."] = "Arnak glaubt, wir würden heiraten ... aber nachdem ich sein Angebot abgelehnt hatte, kam er in jener Nacht zurück und entführte mich. Mein Bruder versuchte, ihn aufzuhalten, aber Arnak war zu stark.",
    ["Wanted: Arnak Grimtotem Arnak the outcast is wanted for the heinous crimes of murder and kidnapping. Handsome rewards will be given to those brave enough to bring this criminal to justice."] = "Gesucht: Arnak Grimmtotem. Arnak der Ausgestoßene wird wegen der abscheulichen Verbrechen Mord und Entführung gesucht. Stattliche Belohnungen werden jenen gewährt, die tapfer genug sind, diesen Verbrecher vor Gericht zu bringen.",
    ["You have the look of a fisherman! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?"] = "Ihr habt den Blick eines Fischers! Ich liebe das Angeln – ich angle mein ganzes Leben lang. Der beste Köder ist weichschaliges Muschelfleisch; die Fische können einfach nicht widerstehen, Ihr wisst, was ich meine?",
    ["Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop."] = "Unter normalen Umständen würden Rigger und ich unsere Kodos an den Kolkar-Zentauren vorbeiführen. Hin und wieder hören wir die Kriegstrommeln der Zentauren, und wenn wir die hören, halten wir an.",
    ["We're sitting on a goldmine here, I tell you - a goldmine! Kodo bones will change the world forever... I have customers making furniture, music instruments, and even blasting powder out of them."] = "Wir sitzen hier auf einer Goldmine, sage ich Euch – einer Goldmine! Kodoknochen werden die Welt für immer verändern ... Ich habe Kunden, die Möbel, Musikinstrumente und sogar Sprengpulver daraus herstellen.",
    ["Well, the only caravan brave enough to travel these parts relies on me. Ever since I learned how to rejuvenate and control aged and dying kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership."] = "Nun, die einzige Karawane, die mutig genug ist, diese Gegenden zu bereisen, verlässt sich auf mich. Seit ich gelernt habe, gealterte und sterbende Kodos mit meinem Kodo-Kombobulator zu verjüngen und zu kontrollieren, gingen der Karawanenbesitzer Cork, Rigger und ich eine Partnerschaft ein.",
    ["Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely."] = "Hier ist etwas eingeschlossener Schlamm, der aus den Teufelswald-Proben entstanden ist, die Ihr geborgen habt. Bringt den Behälter zum Krater von Un'Goro und findet einen reinen Schlamm ... die ursprüngliche Sorte wird sich gut eignen.",
    ["Before you spoke to me, I had heard of your endeavors... that you had an unyielding desire to prove yourself, that you had an exceptional ability as a, and I now know these things to be the truth."] = "Bevor Ihr mit mir gesprochen habt, hatte ich schon von Euren Unternehmungen gehört ... dass Ihr einen unbeugsamen Willen hattet, Euch zu beweisen, dass Ihr außergewöhnliche Fähigkeiten besitzt, und ich weiß nun, dass dies die Wahrheit ist.",
    ["You pick up the sack carefully and prepare to make your way back to Jessir Moonbow on the border of Felwood and Ashenvale. Hopefully the paladin will be given the proper respects once you've passed his remains on to his friends."] = "Ihr hebt den Sack vorsichtig auf und macht Euch bereit, den Weg zurück zu Jessir Moonbow an der Grenze von Teufelswald und Eschental anzutreten. Hoffentlich wird dem Paladin der gebührende Respekt zuteilwerden, sobald Ihr seine sterblichen Überreste seinen Freunden übergeben habt.",
    ["Unfortunately, I see the only way to stop this threat to Felwood is a frontal attack. There are no other ways into Shadow Hold, and I have no means to teleport you inside."] = "Leider sehe ich, dass der einzige Weg, diese Bedrohung für den Teufelswald zu stoppen, ein Frontalangriff ist. Es gibt keinen anderen Weg in die Schattenfeste, und ich habe keine Möglichkeit, Euch hineinzuteleportieren.",
    ["In northern Winterspring, great cats assemble around a large landmark called Frostsaber Rock. The leader of these cats is known by the name Shy-Rotam."] = "Im Norden von Winterquell versammeln sich große Katzen um ein großes Wahrzeichen namens Frostsäblerfels. Der Anführer dieser Katzen ist unter dem Namen Shy-Rotam bekannt.",
    ["While we still know very little about why the furbolg have been ingesting this strange substance, I do think it's best that we put a stop to it before it gets out of hand."] = "Während wir noch immer sehr wenig darüber wissen, warum die Furbolgs diese seltsame Substanz zu sich nehmen, halte ich es für das Beste, dem ein Ende zu setzen, bevor es außer Kontrolle gerät.",
    ["To tell you the truth, although there are no volcanoes here in Winterspring, I believe that there are far more threatening reasons for these hot springs..."] = "Um die Wahrheit zu sagen: Obwohl es hier in Winterquell keine Vulkane gibt, glaube ich, dass es weit bedrohlichere Gründe für diese heißen Quellen gibt ...",
    ["Quite impressive. The crystal of Zin-Malor can never be returned to the temple which, as you know, lies in ruin. But I believe that your effort to undo the evil of the past should not go unrewarded."] = "Recht beeindruckend. Der Kristall von Zin-Malor kann niemals zum Tempel zurückgebracht werden, der, wie Ihr wisst, in Trümmern liegt. Aber ich glaube, dass Euer Bemühen, das Böse der Vergangenheit rückgängig zu machen, nicht unbelohnt bleiben sollte.",
    ["The lifeless hand of the tauren druid clutches a surprisingly healthy looking oaken branch. Examining the branch reveals glyphs of a druidic nature carved into the bark."] = "Die leblose Hand des Tauren-Druiden umklammert einen überraschend gesund aussehenden Eichenzweig. Bei näherer Untersuchung zeigen sich in die Rinde geschnitzte Glyphen druidischer Natur.",
    ["Tampering of the timeline by a sinister force - most likely the Scourge - has occurred in Andorhal! I can try to keep the passage of time here intact and mend what has been damaged, but I'll need your help to do so uninterrupted."] = "In Andorhal wurde die Zeitlinie von einer finsteren Macht – höchstwahrscheinlich der Geißel – manipuliert! Ich kann versuchen, den Lauf der Zeit hier intakt zu halten und zu reparieren, was beschädigt wurde, aber ich brauche Eure Hilfe, um dies ungestört zu tun.",
    ["In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."] = "Bei den Holzschlunds sind wir zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für den Handel. Vor nicht langer Zeit kam eine seltene Nachtelfen-Freundin zu den Holzschlunds, und sie trug einen Runenstoffumhang.",
    ["Daddy told me to give you this key. He said it opens a chest out back behind the house. He also wanted me to thank you. Did you do a favor for him?"] = "Papa hat mir gesagt, ich soll Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe hinten hinter dem Haus. Er wollte sich auch bei Euch bedanken. Habt Ihr ihm einen Gefallen getan?",
    ["Ok, everything is prepared and packed and ready for transport! Good luck in your journey, and make sure you tell Tinkee that she owes me!"] = "Okay, alles ist vorbereitet, verpackt und bereit für den Transport! Viel Glück auf Eurer Reise, und sagt Tinkee unbedingt, dass sie mir etwas schuldet!",
    ["There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts. Sounds scary, doesn't it? Well think how scary it is to the Magram!"] = "Im Südosten gibt es ein Tal, das Tal der Knochen, das von Magram-Geistern heimgesucht wird. Klingt gruselig, nicht wahr? Nun stellt Euch vor, wie gruselig es erst für die Magram ist!",
    ["The amount of salve made out of the reagents you brought me is good enough for ten doses. While I work with the village to try and make some more salve, I'd like for you to help us get a head start."] = "Die Menge an Salbe, die aus den Reagenzien gemacht wurde, die Ihr mir gebracht habt, reicht für zehn Dosen. Während ich mit dem Dorf versuche, mehr Salbe herzustellen, möchte ich, dass Ihr uns helft, einen Vorsprung zu gewinnen.",
    ["You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect. Go now back to your trainer, Mathrengyl Bearwalker, in Darnassus."] = "Ihr habt die notwendigen Lektionen abgeschlossen, die alle jungen Druiden lernen, bevor sie eine Wassergestalt annehmen können. Geht nun zurück zu Eurem Lehrer, Mathrengyl Bärenwanderer, in Darnassus.",
    ["That's fascinating! I have always wondered about the truth... Well, you must share this knowledge, definitely! Go to Arch Druid Fandral Staghelm right away -- you'll find him in Darnassus, in the Cenarion Circle."] = "Das ist faszinierend! Ich habe mich immer über die Wahrheit gewundert ... Nun, Ihr müsst dieses Wissen unbedingt weitergeben! Geht sofort zu Erzdruide Fandral Hirschhaupt – Ihr findet ihn in Darnassus, im Zirkel des Cenarius.",
    ["The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."] = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie haben mehr über verrückte alte Götter, uralte Legenden und Überlieferungen vergessen, als die meisten Gelehrten je wissen werden.",
    ["Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound."] = "Erst kürzlich ist eine große Bande nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie ein großes Gebiet der Wüste in Besitz genommen und ein Lager errichtet.",
    ["I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty."] = "Ich habe diesen Schredder gerade in Ratchet abgeholt und war auf dem Weg zurück zum Holzfällerlager der Kriegshymne, wo ich eigentlich Dienst haben sollte.",
    ["I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients."] = "Ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf die Hand der Schlangenstatue auf der Insel Ranazjar, einer kleinen Insel nordwestlich von hier. Wenn Ihr ihn dort ablegt, wird derjenige beschworen, der das Buch der Uralten beschützt.",
    ["Behold - the Hand of Iruxos. A gruesome sight indeed. You must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do."] = "Seht – die Hand des Iruxos. Wahrlich ein grausiger Anblick. Ihr müsst sie besitzen, wenn die Dämonenportale im Mannoroc-Hexenzirkel gebannt werden sollen ... worum ich Euch nun bitte.",
    ["The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."] = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass der Gegenstand dem Biest irgendwie Energie zuführte. Im Inneren der Kugel schwappt eine faulig aussehende Form von Wasser hin und her.",
    ["Hey!! Come here! My raiders and I are about to attack the Silverwing Outpost to the west. Our target is its leader, Duriel Moonfire. Scouts report the outpost is defended heavily with sentinels and warriors."] = "Hey!! Kommt her! Meine Plünderer und ich sind im Begriff, den Außenposten der Silberschwingen im Westen anzugreifen. Unser Ziel ist ihre Anführerin, Duriel Moonfire. Späher berichten, dass der Außenposten stark mit Schildwachen und Kriegern verteidigt wird.",
    ["Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."] = "Warnung: Betretet den Sishir-Canyon westlich von hier auf eigene Gefahr. Besseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem verwobenen Bau erklärt.",
    ["We are in short supply of a few items at the Warsong lumber camp!"] = "Im Holzfällerlager der Kriegshymne herrscht Mangel an einigen Gegenständen!",
    ["As you have seen, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale."] = "Wie Ihr gesehen habt, ist der Kreislauf des Lebens eine mächtige Sache, obwohl das Land leidet. Nun müssen wir unseren Teil dazu beitragen, ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im Verbrannten Tal.",
    ["Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!"] = "Die Zahl der Blutfurien-Harpyien zu begrenzen wird nicht genügen. Die einzige wahre Heilung für ihre Krankheit wäre, ihren Anführer zu erschlagen, Bloodfury Ripper!",
    ["Yes, imbecile, perhaps you are ready for a more involved set of missions. The albino demon bat, Duskwing, roams the countryside just north of here."] = "Ja, Schwachkopf, vielleicht seid Ihr bereit für eine anspruchsvollere Reihe von Aufträgen. Die albinotische Dämonenfledermaus Duskwing streift im Land direkt nördlich von hier umher.",
    ["Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore. I've lost entire regiments to that monster."] = "Hinter dem Lager der Argentumdämmerung in Lichtshoffnung und westlich von Nordtal findet Ihr das fette Madenungeheuer Borelgore. Ich habe ganze Regimenter an dieses Monster verloren.",
    ["another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."] = "ein weiterer Stamm der Furbolgs, die Foulweald, lebt südöstlich von Astranaar. Sie sind nicht so zahlreich wie die Thistlefur, aber ihre Wildheit stellt eine künftige Bedrohung dar.",
    ["Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King."] = "Malcin behauptet, er sei außerhalb der Hügel der Klingenhauer. Dieser Botschafter muss erschlagen werden – seine Mission ein Fehlschlag in den Augen des Lichkönigs.",
    ["A pit lord left behind when the Legion's invasion collapsed, still holding the Tainted Scar where the Dark Portal's blast burned the land."] = "Ein Grubenlord, der zurückblieb, als die Invasion der Legion zusammenbrach, und der noch immer die Verdorbene Narbe hält, wo die Explosion des Dunklen Portals das Land verbrannte.",
    ["Ragnaros wielded this hammer as the Firelord. Reforging it means taking the Eye of Sulfuras from Ragnaros himself and setting it into the Sulfuron Hammer."] = "Ragnaros führte diesen Hammer als der Feuerlord. Ihn neu zu schmieden bedeutet, das Auge des Sulfuras von Ragnaros selbst zu nehmen und in den Hammer des Sulfuron einzusetzen.",
    ["While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished. Here's the plan: I'm going to give you ten sticks of my special compound."] = "Während Ihr die Vorräte gesammelt habt, ließ ich einige meiner Leute die Gebäude der Geißel markieren, die wir abreißen müssen. Hier ist der Plan: Ich gebe Euch zehn Stangen meiner besonderen Mischung.",
    ["This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."] = "Dieser Anhänger des Zwielichthammers darf seinen Plan nicht vollenden. Der Zwielichthammer versteht die Geister der Natur nicht. Sie glauben an die Alten Götter – Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden.",
    ["A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."] = "Eine Prinzessin der Erdelementare und der Grund, warum Maraudon vergiftet ist – sie hält den Körper von Zaetar, ihrem Halbgott-Gefährten, in seinem Herzen.",
    ["Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship."] = "Tief in Maraudon lebt eine böse Kreatur des Chaos – Prinzessin Theradras ist eine Elementarkraft der Erde, verwandt mit den Alten Göttern. Vor Äonen begannen sie und Zaetar, der erste Sohn des Cenarius, eine Beziehung.",
    ["The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it."] = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon ... Es ist ein uralter Ort mit viel Geschichte. Und ich möchte gern etwas davon in die Hände bekommen.",
    ["A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside. Take this vial."] = "Ein Satyr namens Vyletongue hat die Höhlen von Maraudon verderbt und das Wachstum vieler Pflanzen darin gehemmt. Nehmt diese Phiole.",
    ["You have earned reverence among the Guard. Present your insignia!"] = "Ihr habt Euch Ehrfurcht unter der Garde verdient. Zeigt Euer Abzeichen!",
    ["Rise and be honored! Present your insignia."] = "Erhebt Euch und seid geehrt! Zeigt Euer Abzeichen.",
    ["Your time has come again. You have earned a new ranking and as such, a new insignia denoting this rise in stature."] = "Eure Zeit ist abermals gekommen. Ihr habt einen neuen Rang erlangt und damit ein neues Abzeichen, das diesen Aufstieg anzeigt.",
    ["I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf."] = "Ich hatte nicht erwartet, dass Ihr zurückkehrt. Doch Ihr habt Euch als tapferer und ehrenhafter Soldat der Frostwölfe erwiesen.",
    ["Your radiate command and power, shaman. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name."] = "Ihr strahlt Befehlsgewalt und Macht aus, Schamane. Erhaben in den Augen der Frostwölfe – der Feind duckt sich bei der Erwähnung Eures Namens.",
    ["You have earned the Eye of Command. Present your insignia, Commander."] = "Ihr habt das Auge des Befehls verdient. Zeigt Euer Abzeichen, Kommandant.",
    ["your services to the Warlords surpassed all we could expect from the denizens of this world. We do not understand your people's notions of gratitude, or rewarding good works, but in this case..."] = "Eure Dienste für die Kriegsherren haben alles übertroffen, was wir von den Bewohnern dieser Welt erwarten konnten. Wir verstehen die Vorstellungen Eures Volkes von Dankbarkeit oder der Belohnung guter Taten nicht, aber in diesem Fall ...",
    ["Anyway, you should check back with me relatively soon... that is if you want to know what was in here. As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you."] = "Jedenfalls solltet Ihr relativ bald wieder bei mir vorbeischauen ... das heißt, wenn Ihr wissen wollt, was hier drin war. Sobald ich herausfinde, was es ist, und falls es tatsächlich ein Buch ist, teile ich Euch diese Information gern mit.",
    ["Overlord Runthak awaits your arrival in the Valley of Strength. Do not keep your public waiting, hero."] = "Oberherr Runthak erwartet Eure Ankunft im Tal der Stärke. Lasst Euer Publikum nicht warten, Held.",
    ["The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."] = "Der Feuerlord, einer der vier Elementarlords, gebunden an die Elementarebene, bis die Dunkeleisenzwerge ihn unter dem Schwarzfels beschworen. Die Beschwörung ließ den Berg aufbrechen und schuf den Geschmolzenen Kern.",
    ["A hound handler of Ragnaros's court, who curses healing shut before the fighting starts."] = "Ein Hundeführer aus dem Hofstaat des Ragnaros, der Heilung verflucht, bevor der Kampf beginnt.",
    ["Avast Lubber! Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!"] = "Ahoi, Landratte! Bringt mir 12 Schmuckstücke des Arenameisters, und Ihr sollt ein Großmeister der Gurubashi-Arena sein!",
    ["You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."] = "Ihr habt Eure Sache doppelt gut gemacht, als Ihr Euch der Bedrohung durch die Zukk'ash-Insekten für das Lager Mojache gewidmet habt. Die Bedrohung durch diese Wesen ist noch lange nicht vorbei, und ich möchte Euch im Namen der Horde um eine letzte Aufgabe bitten.",
    ["When doing this though, be sure to save me the water elemental cores!"] = "Wenn Ihr das tut, bewahrt mir unbedingt die Wasserelementarkerne auf!",
    ["I have a lead on an even BETTER source of hides, if that's even possible to believe! In the northern parts of Feralas - deep within Rage Scar Hold - are another throng of yetis."] = "Ich habe einen Hinweis auf eine NOCH BESSERE Quelle für Felle, wenn man das überhaupt glauben kann! Im Norden von Feralas – tief in der Wutnarbenfeste – lebt eine weitere Horde Yetis.",
    ["The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power."] = "Die einfallenden Sturmlanzen sind nicht die einzige Bedrohung in der Region, Soldat. Der Krieg im Tal wird an zwei Fronten geführt. Auch die kannibalischen Winterax-Trolle ringen um die Macht.",
    ["Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you."] = "Kehrt zu meiner Gefährtin zurück, Urahnin Torntusk im Dorf der Revantusk. Sagt ihr, dass ich nach Hause komme! Sie wird Euch sicher belohnen.",
    ["Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."] = "Wie viele in unserem Dorf habe auch ich einen geliebten Menschen an die Wildnis verloren. Leider war es mein Zwillingsbruder Malkhor – bei demselben Überfall verschleppt wie Torntusks Gefährte, von den Vilebranch.",
    ["You take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business!"] = "Nehmt das, Mann. Ihr bringt das zum Nistgipfel, mitten in der Stadt beim Brunnen. Ihr pflanzt es! Treibt es direkt in den Boden! Zeigt diesen Zwergen, dass Troll es ernst meint!",
    ["With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."] = "Mit dem Verlust von Gardehauptmann Malkhor ist der Posten des Gardehauptmanns der Revantusk wieder frei.",
    ["By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."] = "Auf Befehl von Urahnin Torntusk sollen die üble Priesterin Hexx und ihre Gefolgsleute vor Gericht gebracht werden! Eine große Belohnung wird für jeden ausgesetzt, der die üble Priesterin Hexx und ihre gesamte Aman'zasi-Eliteleibwache erschlägt.",
    ["The following items have been stolen: *One Dark Iron Tuyere. *One Lookout's Spyglass. A reward is being offered to individuals who find and return these pilfered items."] = "Folgende Gegenstände wurden gestohlen: *Eine Dunkeleisen-Windform. *Das Fernrohr eines Ausgucks. Eine Belohnung wird jenen geboten, die diese entwendeten Gegenstände finden und zurückbringen.",
    ["By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."] = "Auf Befehl Seiner Eminenz, Aufseher Oilfist, ist der abtrünnige Agent der Thoriumbruderschaft und neu angeheuerte Kommandant der Dunkeleisen-Schlackengrubenmannschaft des Kessels, Aufseher Maltorius, zu töten, und sein Kopf als Beweis der Tat zurückzubringen.",
    ["A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."] = "Ein roter Drache aus dem Schwarm Alexstraszas, gebrochen durch Nefarians Experimente. Er bittet darum, getötet zu werden, bevor die Verderbnis ihn ganz einnimmt, und entschuldigt sich, während er kämpft.",
    ["Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."] = "Deathwings Sohn, der unter dem Schwarzfels daran arbeitet, den chromatischen Schwarm zu züchten – Drachen, die das Blut aller fünf in sich tragen. Er verbrachte Jahre am Hof von Sturmwind als Lord Victor Nefarius, während die Arbeit voranschritt.",
    ["One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."] = "Einer von drei Drachen, die Nefarians inneren Unterschlupf bewachen, und derjenige, der sich an den Wunden heilt, die er zufügt.",
    ["Cut from the fang of one of Nefarian's drakes. Tanks wore it for the stun it shrugs off, not the numbers on it."] = "Aus dem Fangzahn eines von Nefarians Drachen geschnitten. Tanks trugen ihn wegen der Betäubung, die er abschüttelt, nicht wegen der Werte darauf.",
    ["The last of Nefarian's three drakes, and the one that simply gets angrier as the fight goes on."] = "Der letzte von Nefarians drei Drachen, und derjenige, der im Laufe des Kampfes einfach immer wütender wird.",
    ["The ultimate symbol of a haruspex's power is what they wear."] = "Das ultimative Symbol der Macht eines Haruspex ist das, was er trägt.",
    ["We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around."] = "Wir Zandalar kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden, nicht umgekehrt.",
    ["By communion with animals and givin' them up to the spirits when needed, they give us divine guidance. In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi."] = "Durch Zwiesprache mit Tieren und indem sie sie, wenn nötig, den Geistern übergeben, schenken sie uns göttliche Führung. In vergangenen Zeiten verschafften uns die Einsicht und Weisheit der Haruspexe einen Vorteil in den Kriegen gegen die zersplitterten Stämme der Gurubashi.",
    ["Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose."] = "Hakkars oberster Hexer, der kämpft, indem er Teile der Geister seiner Feinde bindet und freilässt.",
    ["He must be stopped! Take this sacred cord, and string through it the heads of the high priests responsible for channeling our gods' energy."] = "Er muss aufgehalten werden! Nehmt diese heilige Schnur und fädelt die Köpfe der Hohepriester darauf auf, die dafür verantwortlich sind, die Energie unserer Götter zu kanalisieren.",
    ["My delvings into the Mosh'aru Tablets bear grim news. Hakkar's true form, the god himself, can be born again through the very egg into which you captured him."] = "Meine Nachforschungen in den Mosh'aru-Tafeln bergen düstere Nachrichten. Hakkars wahre Gestalt, der Gott selbst, kann durch eben jenes Ei, in das Ihr ihn gebannt habt, wiedergeboren werden.",
    ["One of Ysera's four green consorts, corrupted by the Emerald Nightmare and now roaming Feralas, rotting the ground it stands on."] = "Einer von Yseras vier grünen Gefährten, vom Smaragdgrünen Albtraum verderbt und nun in Feralas umherstreifend, wobei er den Boden verrotten lässt, auf dem er steht.",
    ["The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing."] = "Das Wasser des Sees Elune'ara sollte die Albträume auflösen, die diesen Gegenstand verschlingen. Gebt mir einen Moment, um die Reinigung durchzuführen.",
    ["A Nightmare-corrupted green dragon who splits himself into shades rather than face a fight whole."] = "Ein vom Albtraum verderbter grüner Drache, der sich lieber in Schatten aufspaltet, als einem Kampf ganz entgegenzutreten.",
    ["They want the impossible from me! The Steamwheedle Cartel wants me to teach the Southsea pirates a lesson."] = "Sie verlangen das Unmögliche von mir! Das Dampfdruckkartell will, dass ich den Piraten des Südmeers eine Lektion erteile.",
    ["The terrible scorpid, Deathclasp, is believed to have retreated to the southern mountain range in the presence of increased silithid activity."] = "Der schreckliche Skorpid Deathclasp soll sich angesichts verstärkter Silithidenaktivität in die südliche Bergkette zurückgezogen haben.",
    ["We have discovered another base of operations for the Twilight's Hammer. It is called Twilight's Run; it is a cave tucked in the northeast corner of Silithus."] = "Wir haben einen weiteren Operationsstützpunkt des Zwielichthammers entdeckt. Er heißt Zwielichtlauf; es ist eine Höhle, versteckt in der nordöstlichen Ecke von Silithus.",
    ["I need you to venture into Hive'Regal and find what became of my dearest Natalia. This will be no easy task for you. Before you dive headlong into the maw of madness, make sure that you go back and speak with those dwarves."] = "Ich brauche Euch, damit Ihr Euch in Hive'Regal wagt und herausfindet, was aus meiner liebsten Natalia wurde. Das wird keine leichte Aufgabe für Euch. Bevor Ihr Euch kopfüber in den Schlund des Wahnsinns stürzt, geht zurück und sprecht mit diesen Zwergen.",
    ["An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."] = "Ein Alter Gott, von den Titanen unter Ahn'Qiraj begraben, statt getötet zu werden. Seitdem flüstert er den Qiraji zu, und der ganze Krieg existiert, weil er nie damit aufgehört hat.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them."] = "Die Abzeichen, die Ihr für Kampf-, Logistik- und Taktikaufträge für Burg Cenarius sammelt, sind mehr als nur Zierde. Ihr tätet gut daran, sie aufzubewahren.",
    ["The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."] = "Die Abzeichen, die Ihr für Kampf-, Logistik- und Taktikaufträge für Windrufer Stolzhorn sammelt, sind mehr als nur Zierde. Ihr tätet gut daran, sie aufzubewahren.",
    ["I speak of Elementium, mortal. Find and bring me Imperial Qiraji Regalia and the toxic element and I shall infuse weapons of great power."] = "Ich spreche von Elementium, Sterblicher. Findet und bringt mir kaiserliche Qiraji-Insignien und das giftige Element, und ich werde Waffen von großer Macht erfüllen.",
    ["The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe."] = "Die Holzschlunds sind der einzige Furbolg-Stamm, der der Verderbnis entkommen ist. Doch viele andere Völker töten Furbolgs nun blindlings, ohne sich die Mühe zu machen, zu prüfen, ob sie Freund oder Feind sind.",
    ["There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."] = "Direkt südwestlich von uns liegt ein Lager der Totenwald-Furbolgs. Verderbnis durchdringt das Lager, und ich möchte dem ein Ende bereiten, bevor sie zu einem Problem werden.",
    ["The Timbermaw tend to stay to themselves. While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible."] = "Die Holzschlunds bleiben meist unter sich. Auch wenn wir denen, denen wir vertrauen, sicheres Geleit gewähren, versuchen wir, andere Furbolg-Stämme nach Möglichkeit zu meiden.",
    ["The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."] = "Die Zwillingskaiser ... ihr unaufhörliches Flüstern zehrt langsam an meinem Verstand. Sie verspotten mich, da sie wissen, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.",
    ["It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."] = "Es heißt unter uns, dass die verzierten Schulterrüstungen der sterblichen Völker als Versuch begannen, die Flügel eines Drachen nachzuahmen.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of dominance and other minor components by and I'll create a set of powerful boots for you."] = "Die mächtigsten Qiraji führen Gegenstände von solcher Macht, dass sie selbst einen Drachen innehalten lassen. Bringt mir die Qiraji-Fesseln der Herrschaft und andere kleinere Bestandteile, und ich fertige Euch ein Paar mächtige Stiefel.",
    ["You seek to prove your worth to my kind, mortal? Very well, perhaps we can be of mutual assistance. The ancient sandworm, Ouro, is a being of legendary power."] = "Ihr wollt Euch meinem Volk gegenüber beweisen, Sterblicher? Nun gut, vielleicht können wir einander gegenseitig helfen. Der uralte Sandwurm Ouro ist ein Wesen von legendärer Macht.",
    ["The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."] = "Der namenlose Alte Gott erwacht langsam aus seinem Schlummer unter Ahn'Qiraj. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder Jahren kommen; die Zeit hat für Wesen seiner Macht keine Bedeutung.",
    ["The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong."] = "Die Qiraji und ihre Diener führen Gegenstände, die aus den seltensten und feinsten Materialien gefertigt sind: Knochen gewaltiger uralter Kreaturen, Edelsteine aus den Tiefen der Erde, reine und starke Metalle.",
    ["The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities. The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings."] = "Den Ringen, die die Qiraji-Leutnants tragen, sagt man nach, dass sie ihnen gewaltige Fähigkeiten verleihen. Die verderbten Edelsteine, die sie zieren, könnten theoretisch gegen reinere Materialien ausgetauscht werden, um unverderbte Versionen der Ringe herzustellen.",
    ["I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."] = "Ich freue mich zu hören, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj helft. Ich kann Euch einen Schutzgegenstand anfertigen, der im Kampf gegen unseren Feind hilfreich sein wird.",
    ["A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."] = "Eine schreckliche Bedrohung wurde zur Ruhe gebettet. Der grausame Ossirian wurde besiegt. Die Bewohner Kalimdors wären erleichtert, von diesem Sieg zu erfahren.",
    ["I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book!"] = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, mit seinen alten Tricks! Und jetzt, dank Eures Versagens in Winterquell, hat Doktor Weavil mein Buch zerstört!",
    ["Did I mention the bad news yet? Its name is Maws: 100 feet of death and destruction. I guess I may have forgotten that little tidbit."] = "Habe ich die schlechte Nachricht schon erwähnt? Ihr Name ist Maws: 100 Fuß Tod und Verwüstung. Ich schätze, dieses kleine Detail habe ich vergessen.",
    ["Champion, is it you? A thousand years it has been since I was entrusted the shard and it is at my darkest hour that one should rise to relieve me of it..."] = "Champion, seid Ihr es? Tausend Jahre ist es her, seit mir der Splitter anvertraut wurde, und in meiner dunkelsten Stunde sollte sich einer erheben, um mich davon zu befreien ...",
    ["We must use restraint against Eranikus. We are to redeem him not destroy him. Tyrande is already en route to assist us in this task. We must weather the dragon's blows and save Nighthaven from certain destruction."] = "Wir müssen gegen Eranikus Zurückhaltung üben. Wir sollen ihn erlösen, nicht vernichten. Tyrande ist bereits unterwegs, um uns bei dieser Aufgabe zu helfen. Wir müssen den Schlägen des Drachen standhalten und Nachthafen vor der sicheren Zerstörung bewahren.",
    ["Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."] = "Zwillingskaiser der Qiraji, und derjenige, der C'Thuns Gabe für die Magie erbte statt der Stärke seines Bruders. Keiner der Zwillinge kann weit vom anderen entfernt getötet werden.",
    ["Twin emperor of the qiraji, and the stronger arm of the pair. Kill one and the other heals him, so both must fall together."] = "Zwillingskaiser der Qiraji, und der stärkere Arm des Paares. Tötet einen, und der andere heilt ihn, sodass beide gemeinsam fallen müssen.",
    ["A sandworm grown enormous under the desert, surfacing only to feed."] = "Ein Sandwurm, der unter der Wüste gewaltig herangewachsen ist und nur auftaucht, um zu fressen.",
    ["A qiraji brood matron whose poison is potent enough that the fight is really a race against her venom."] = "Eine Qiraji-Brutmatrone, deren Gift so stark ist, dass der Kampf in Wahrheit ein Wettlauf gegen ihr Gift ist.",
    ["A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."] = "Ein gewaltiger Qiraji-Wühler, der mitten im Kampf seine Jungen hervorbringt und Eindringlinge gegen die Wände schleudert.",
    ["The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."] = "Der beste Soldat des Qiraji-Imperiums, der mit ihrer Ehrengarde kämpft und sich weigert, sich von ihr trennen zu lassen.",
    ["A living mass of qiraji poison. It has to be frozen solid and then shattered, which is not how most things die."] = "Eine lebende Masse aus Qiraji-Gift. Sie muss tiefgefroren und dann zerschmettert werden, was nicht die Art ist, auf die die meisten Dinge sterben.",
    ["One of the three qiraji councillors who fight as one -- kill any of them and the survivors grow stronger."] = "Einer der drei Qiraji-Ratsmitglieder, die als eins kämpfen – tötet einen von ihnen, und die Überlebenden werden stärker.",
    ["The third of the qiraji council, who charges the moment the fight begins and does not stop."] = "Der dritte des Qiraji-Rates, der im Moment des Kampfbeginns losstürmt und nicht mehr aufhört.",
    ["C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."] = "C'Thuns Sprachrohr. Alles, was die Qiraji glauben, glauben sie, weil er ihnen sagte, der Alte Gott habe es gesagt.",
    ["To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."] = "Zu den Höhlen der Zeit geht Ihr, Lord:Lady;. Anachronos erwartet Eure Rückkehr. Gebt ihm das Auge von C'Thun, denn er wird zweifellos wünschen, es in die Sammlung seines Meisters aufzunehmen.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."] = "Ich glaube, eine Belohnung ist angebracht, wenn ich Euch weiter dafür interessieren will, meine Haut zu retten. Bringt mir den Gürtel und das Paar Handschuhe, die Ihr verbessern möchtet.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."] = "Valthalaks Seele wurde in diesem Amulett aufbewahrt. In unserer Gier teilten wir es töricht in drei Teile, ohne den Fluch zu kennen, der uns erwartete. Der einzige Weg, Valthalaks Zauber zu stoppen, ist, das Medaillon wieder zusammenzusetzen.",
    ["I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality. I'd be willing to trade the bracers for ordinary ones in exchange for a small favor."] = "Ich besitze eine Rüstung, ähnlich der, die Leute Eures Berufs tragen, aber von weit höherer Qualität. Ich wäre bereit, die Armschienen gegen gewöhnliche einzutauschen, im Austausch für einen kleinen Gefallen.",
    ["That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."] = "Das ist eine erstaunliche Geschichte! Ihr habt meinen Dank und die herzliche Dankbarkeit aller Beteiligten. Vielleicht kann ich nun nachts wieder mit beiden Augen zu schlafen.",
    ["Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."] = "Doch ich bin keiner, der Gefallen leichtfertig verteilt, auch wenn Euch ein alter Freund geschickt hat. Ich hege nichts als Hass und Verachtung für unsere brutalen Ogernachbarn.",
    ["My brother and I run the poison operations out of the manor Ravenholdt."] = "Mein Bruder und ich leiten die Giftgeschäfte vom Herrenhaus Rabenholdt aus.",
    ["From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes."] = "Von den Leichen der Gefallenen wird die Rüstung abgestreift und nach Naxxramas zurückgebracht, um zu unbekannten Zwecken verwendet zu werden.",
    ["The Guardian's staff, broken and scattered. Rebuilding it means gathering forty splinters from Naxxramas, the base from Kel'Thuzad, and carrying it to the ruin of Karazhan where Medivh once held it."] = "Der Stab des Wächters, zerbrochen und verstreut. Ihn wiederherzustellen bedeutet, vierzig Splitter aus Naxxramas und die Basis von Kel'Thuzad zu sammeln und ihn zur Ruine von Karazhan zu tragen, wo Medivh ihn einst hielt.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial wrists."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun Gletscher-Armschienen herstellen.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power?"] = "Seid gegrüßt, Freund. Habt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gegen Gegenstände von großer Macht eintauschen möchtet?",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Glacial cloak."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun einen Gletscher-Umhang herstellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create a Polar tunic."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun eine Polartunika herstellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar gloves."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun Polarhandschuhe herstellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Polar bracers."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun Polararmschienen herstellen.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of great power? I must warn you; purchases made at a friendly reputation with the Dawn come with an extremely hefty surcharge."] = "Seid gegrüßt, Freund. Habt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gegen Gegenstände von großer Macht eintauschen möchtet? Ich muss Euch warnen: Käufe bei freundlichem Ruf bei der Dämmerung sind mit einem extrem hohen Aufpreis verbunden.",
    ["Greetings, friend. Have you insignias of the Dawn or the Crusade that you would like to redeem for items of power? I must warn you; purchases made at a friendly reputation with the Dawn come with a hefty surcharge."] = "Seid gegrüßt, Freund. Habt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gegen Gegenstände von Macht eintauschen möchtet? Ich muss Euch warnen: Käufe bei freundlichem Ruf bei der Dämmerung sind mit einem hohen Aufpreis verbunden.",
    ["You fancy yourself a hero of the Dawn, eh? I've seen our greatest soldiers get rolled over by Kel'Thuzad's plebes! How well could someone so clueless possibly fare in Naxxramas?"] = "Ihr haltet Euch für einen Helden der Dämmerung, was? Ich habe gesehen, wie unsere größten Soldaten von Kel'Thuzads Pöbel überrollt wurden! Wie gut könnte jemand, der so ahnungslos ist, in Naxxramas wohl abschneiden?",
    ["A crypt lord of Azjol-Nerub who took Arthas's side. He holds the Arachnid Quarter's outermost hall."] = "Ein Gruftlord von Azjol-Nerub, der sich auf Arthas' Seite schlug. Er hält die äußerste Halle des Spinnenviertels.",
    ["A worshipper of Kel'Thuzad who brought her followers with her into undeath, and still commands them."] = "Eine Anbeterin Kel'Thuzads, die ihre Anhänger mit sich in die Untotheit brachte und sie noch immer befehligt.",
    ["A giant spider webbed into the depths of the Arachnid Quarter, fed on whatever the Scourge no longer needs."] = "Eine Riesenspinne, in die Tiefen des Spinnenviertels eingesponnen, die sich von allem nährt, was die Geißel nicht mehr braucht.",
    ["An abomination stitched together from the Scourge's leftovers, built for nothing but raw strength."] = "Eine aus den Überresten der Geißel zusammengenähte Abscheulichkeit, für nichts als rohe Stärke gebaut.",
    ["A stitched hound kept half-starved on purpose, so it would eat anything the Construct Quarter sent its way."] = "Ein zusammengenähter Hund, absichtlich halb verhungert gehalten, damit er alles frisst, was das Konstruktviertel ihm schickt.",
    ["A death knight who trains the Scourge's new officers. He is too strong for his own students to touch, which is exactly the point of the lesson."] = "Ein Todesritter, der die neuen Offiziere der Geißel ausbildet. Er ist zu stark, als dass seine eigenen Schüler ihn berühren könnten, und genau das ist die Lektion.",
    ["Razuvious's colleague in the Military Quarter, who fights from behind his own dead and keeps sending them forward."] = "Razuvious' Kollege im Militärviertel, der hinter seinen eigenen Toten kämpft und sie immer weiter nach vorn schickt.",
    ["A necromancer of the Plague Quarter, promoted for his skill at raising what he had just finished killing."] = "Ein Nekromant des Seuchenviertels, befördert für sein Geschick darin, wiederzuerwecken, was er gerade erst getötet hatte.",
    ["Keeper of Naxxramas's plague works, and of the corridor of eruptions that has killed more raiders than he has."] = "Hüter der Seuchenwerke von Naxxramas und des Korridors der Eruptionen, der mehr Plünderer getötet hat als er selbst.",
    ["A fungal horror grown in the Plague Quarter's spore vats -- less a creature than a crop that got out of hand."] = "Ein Pilzschrecken, in den Sporenbottichen des Seuchenviertels gezüchtet – weniger eine Kreatur als eine Ernte, die außer Kontrolle geraten ist.",
    ["A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."] = "Ein blauer Drache, in Nordend erschlagen und als Frostwyrm wiedererweckt. Er bewacht den letzten Zugang zu Kel'Thuzads Kammer.",
    ["Once an archmage of the Kirin Tor, he left Dalaran to found the Cult of the Damned and served Ner'zhul willingly. Killed at Andorhal and raised as a lich, he rules Naxxramas from a phylactery at its heart."] = "Einst ein Erzmagier des Kirin Tor, verließ er Dalaran, um den Kult der Verdammten zu gründen, und diente Ner'zhul freiwillig. In Andorhal getötet und als Lich wiedererweckt, herrscht er von einem Phylakterium in seinem Herzen aus über Naxxramas.",
    ["Here's your cask of Evershine. And again, thank you for the hunting earlier."] = "Hier ist Euer Fass Ewigglanz. Und nochmals Dank für die Jagd von vorhin.",
    ["Recently, a new group of thieves has been hanging around Northshire. They call themselves the Defias Brotherhood, and have been seen across the river to the east."] = "Seit Kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die Defias-Bruderschaft und wurden jenseits des Flusses im Osten gesehen.",
    ["The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff. First you must pass the Rite of Strength."] = "Die Riten der Erdmutter sind die Schritte, die ein junger Tauren gehen muss, um in Donnerfels Respekt zu erlangen. Zuerst müsst Ihr den Ritus der Stärke bestehen.",
    ["My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances."] = "Mein Bruder Senir und ich wurden in verschiedene Teile von Dun Morogh geschickt, um die Bedrohung durch die Trolle zu untersuchen. Der Senat hat mit den Troggs alle Hände voll zu tun, da braucht er keine weiteren Plagen.",
    ["Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest. According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew."] = "Scharlachrote Kreuzfahrer haben von dem zerstörten Turm im Norden von Tirisfal, jenseits von Faols Ruh, aus Überfälle verübt. Nach unseren Informationen führt ein rücksichtsloser Kommandant namens Hauptmann Melrache diese üble Truppe an.",
    ["Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young. The Wildmane Totem is made, and your last task lies ahead."] = "Eure Reinigung der Brunnen von Winterhuf und Donnerhorn wird unter den Geistern besprochen, Junger. Das Wildmähnen-Totem ist gefertigt, und Eure letzte Aufgabe liegt vor Euch.",
    ["Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\" I can't deal with losing all our caravans, so I'm just going to take matters into my own hands."] = "Gazlowe sagte mir einmal: „Rezlak. Es gibt eine Sache, die Ihr im Leben wissen müsst: Wenn Ihr wollt, dass etwas gut gemacht wird, macht es selbst.“ Ich kann nicht damit leben, all unsere Karawanen zu verlieren, also nehme ich die Dinge einfach selbst in die Hand.",
    ["My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that."] = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Derjenige, der es hatte ... Es war ein großer Rohling mit seltsamen Zeichen auf Haut und Gesicht. Mehr habe ich nicht erkennen können.",
    ["Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw."] = "Ohne den Segen von Alexstrasza der Lebensbinderin und Nozdormu dem Zeitlosen ist Teldrassils Wachstum nicht ohne Makel gewesen.",
    ["You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts. We can now turn our eyes to other concerns."] = "Ihr werdet froh sein zu hören, dass wir in der Mine offenbar Fortschritte machen, nicht zuletzt dank Eurer Bemühungen. Wir können uns nun anderen Sorgen zuwenden.",
    ["Two extra attacks on a proc, on a fast axe. Warriors farmed Dire Maul for this one item and nothing else."] = "Zwei zusätzliche Angriffe bei einem Auslöser, auf einer schnellen Axt. Krieger farmten Düsterbruch für diesen einen Gegenstand und nichts anderes.",
    ["We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us."] = "Wir waren tief in einer riesigen Mine in Westfall, versteckt unter einer Scheune in Moonbrook. Keine Ahnung, woher diese stinkenden Diebe kamen. Jedenfalls ist der Minenstollen über uns eingestürzt.",
    ["Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened."] = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht ... irgendwie ... wird er wissen, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.",
    ["Stalvan Mistmantle led a life of depravity. Innocent victims died by his hand. Undoubtedly he is guilty of countless crimes. Now the lunatic threatens Darkshire."] = "Stalvan Mistmantle führte ein Leben der Verderbtheit. Unschuldige Opfer starben durch seine Hand. Zweifellos ist er unzähliger Verbrechen schuldig. Nun bedroht der Irre Dunkelhain.",
    ["I do not know why, but a festering grows within the Wetlands. Fen Creepers have risen. They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes."] = "Ich weiß nicht, warum, aber im Sumpfland breitet sich eine Eiterung aus. Fen Creepers haben sich erhoben. Sie sind kranke, fiebrige Blasen auf dem Land, und damit das Fieber sinkt, müssen sie getötet werden und sich wieder in den Sümpfen setzen können.",
    ["Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it."] = "Glaubt Ihr, Ihr könnt Euch geistig mit Daryl dem Kühnen messen, hm? Das glaube ich nicht! Natürlich seid Ihr herzlich eingeladen, es zu versuchen. Hier ist eine Herausforderung, die Eure Fähigkeiten übersteigen dürfte, also grämt Euch nicht allzu sehr, wenn Ihr ihr nicht gewachsen seid.",
    ["Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols. But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!"] = "Kürzlich, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Zahl seltsamer, geschnitzter Götzen entdeckt. Aber wir hatten keine Gelegenheit, sie zu studieren, denn kurz nach ihrer Entdeckung jagten uns die Troggs aus den Ruinen!",
    ["Now that the catapults have been burned, find and kill Chieftain Nek'rosh."] = "Jetzt, da die Katapulte verbrannt sind, findet und tötet Häuptling Nek'rosh.",
    ["Murlocs are becoming a problem. Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!"] = "Murlocs werden zum Problem. Größere Gruppen der Fischmenschen werfen entlang der Ufer des Ewigstillsees Anker und fischen auf Teufel komm raus!",
    ["ath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat. You should try your hand at boar hunting."] = "ath, ja? Ich sehe, Ihr platzt vor Stolz, den ersten Test bestanden zu haben, hm? Wie ich Euch schon sagte, ist das keine große Leistung. Ihr solltet Euch an der Wildschweinjagd versuchen.",
    ["Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate."] = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um einen Gegenstand aus Durnholde zu holen und dieses sogenannte Syndikat zu untersuchen.",
    ["The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace..."] = "Der Anhänger? Natürlich dürft Ihr ihn haben ... Nehmt ihn! Ich will keine Erinnerung an ihn ... bitte, bitte geht einfach in Frieden ...",
    ["To survive, I have to be tricky! I know the recipe for flash bombs."] = "Um zu überleben, muss ich gerissen sein! Ich kenne das Rezept für Blendbomben.",
    ["He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!"] = "Diesmal hat er es geschafft! Schlimm genug, dass Gelriz die Mogule verdrängt, die von den Handelsfürsten eingesetzt wurden, nun versucht er auch noch, sich beim berüchtigtsten Piraten einzumischen!",
    ["You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself. You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!"] = "Ihr habt Euch immer wieder bewährt, und Euer Einfallsreichtum scheint sogar den von Kurzen selbst zu übertreffen. Ihr könntet die Rettung unserer Rebellenbande sein ... wenn Ihr es mit Kurzen aufnehmen und bestehen könnt!",
    ["The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto. Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts."] = "Die Stromgarde-Miliz hat Kopfgelder auf die Köpfe von Lord Falconcrest und seinem Leibwächter Otto ausgesetzt. Falconcrest leitet die Bemühungen des Syndikats im Arathihochland, und sein Tod würde diese Bemühungen erheblich stören.",
    ["You serve my husband well, but he does not know why Hammerfall is under attack."] = "Ihr dient meinem Mann gut, aber er weiß nicht, warum Hammerfall angegriffen wird.",
    ["Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman. It has already meant tremendous casualties for our people, but it has obviously grown worse."] = "Botschafter Infernus wurde von Ragnaros persönlich zur Festung Angor geschickt, um die Schattenschmiede bei der Suche nach verlorenen Artefakten in Uldaman zu beaufsichtigen. Das hat unserem Volk bereits enorme Verluste gebracht, aber es ist offensichtlich noch schlimmer geworden.",
    ["Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil."] = "Prospektor Whelgar hält das ursprüngliche Fossil nun an seiner Stätte im Sumpfland. Als ich den Stein von Relu entdeckte, glaubte ich, er sei der Schlüssel, um das Geheimnis des Fossils zu lüften.",
    ["When I struggled with the Forsaken's poisons, I had a vision. I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!"] = "Als ich mit den Giften der Verlassenen rang, hatte ich eine Vision. Ich hatte eine Vision von den Druiden im Dor'danil-Hügelgrabbau, vergiftet ... ermordet von den Untoten!",
    ["We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions."] = "Wir werden das Worgenproblem eindämmen, seid unbesorgt. Dieses Übel, das Eure Freundin in unsere Wälder brachte, wird eingedämmt werden, und ich hege keinen Groll gegen sie für ihre Taten.",
    ["It makes them go berserk! Bring me 8 idols - I want to study them, and I want them out of Trogg hands!"] = "Es macht sie rasend! Bringt mir 8 Götzen – ich will sie studieren, und ich will sie aus den Trogg-Händen haben!",
    ["Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon."] = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, Moktar macht gute Arbeit für ihn in Tausend Nadeln. Sagt ihm auch, dass meine Studien vorankommen und ich hoffe, bald mehr gelernt zu haben.",
    ["It took a long time, but I found Reethe. He hide good for a human. Ogron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him."] = "Hat lange gedauert, aber ich Reethe gefunden. Er sich gut versteckt für Mensch. Ogron Sorge, dass er verrückt nach so langer Zeit im Sumpf. Ihr mit mir kommen, wir ihm Antworten holen.",
    ["I am so lost! My wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere. Would you be so kind as to lead me back to Torta?"] = "Ich bin so verirrt! Meine Frau Torta hat mich geschickt, das Abendessen zu holen, und ich muss irgendwo falsch abgebogen sein. Wärt Ihr so freundlich, mich zurück zu Torta zu führen?",
    ["The venom you gathered from the Witherbark's spider god is quite a find! I've been able to kill nearly two dozen rabbits with just a drop of the stuff."] = "Das Gift, das Ihr vom Spinnengott der Witherbark gesammelt habt, ist ein echter Fund! Ich konnte mit nur einem Tropfen davon fast zwei Dutzend Kaninchen töten.",
    ["If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it. She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere."] = "Wenn Ihr so freundlich wärt, das Relikt meiner Frau Vestia zu überbringen, wäre ich Euch dankbar. Sie ist nicht nur eine feine Priesterin für unsere Gemeinschaft, sondern eine der belesensten Gelehrten, die Ihr überall finden werdet.",
    ["Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal."] = "Edana Hatetalon ist die Königin der Harpyien von Nordquell, die in den Ruinen im Westen hausen. Sie ist das reine Böse; ich habe gehört, ihr Herz sei aus Kristall.",
    ["You dare challenge Overlord Mok'Morokk? Haw! Me crush tiny! You tell me when ready for good beating."] = "Ihr wagen Oberherr Mok'Morokk herausfordern? Ha! Ich zerquetsch Kleinen! Ihr sagen, wenn bereit für gute Tracht Prügel.",
    ["Listen well. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue."] = "Hört gut zu. Während die vier Türme niemals zerstört werden können, könnt Ihr die Fackel der Vergeltung benutzen, um sie für sehr lange Zeit in Brand zu setzen: ein Feuer, das kein Element und keine Macht bezwingen kann.",
    ["Just one last thing you must do, soldier. I've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground."] = "Nur eine letzte Sache müsst Ihr tun, Soldat. Ich habe mir die Freiheit genommen, Gor'teshs Kopf auf eine Pike zu spießen. Nun müsst Ihr nur noch diesen Kopf auf die Spitze des Schreckensfelsens bringen und in den Boden rammen.",
    ["While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north."] = "Während Ihr Un'Goro erkundet habt, habe ich andere Dinge gesehen, an denen sich ein mächtiger Jäger wie Ihr erfreuen würde. Ein solcher Anblick war ein riesiger Affe unter den anderen Gorillas im Norden.",
    ["Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area."] = "Gesucht: Ein geschickter Kämpfer, der sich der Bedrohung durch die Pterrordax annimmt, die den Krater von Un'Goro bewohnen. Ihre Zahl wächst, und sie werden zur Gefahr für Reisende in der Gegend.",
    ["I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."] = "Ich werde mehr Proben brauchen. Aber – und ich weiß nicht, wie ich das sagen soll – es müssen reine Proben sein. Ich weiß, ich weiß. „Was heißt denn ‚rein‘, Laris?“ Ich bin mir nicht sicher.",
    ["The blade the Silver Hand carried against the Scourge, and the one Tirion Fordring's order was built around. Corrupted when Renault Mograine used it on his own father, Alexandros, in the Scarlet Monastery."] = "Die Klinge, die die Silberne Hand gegen die Geißel führte, und diejenige, um die Tirion Fordrings Orden aufgebaut wurde. Verderbt, als Renault Mograine sie gegen seinen eigenen Vater Alexandros im Scharlachroten Kloster einsetzte.",
    ["You look like a capable. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!"] = "Ihr seht fähig aus. Vielleicht wollt Ihr etwas Geld verdienen? Cork und ich haben diese Karawane gegründet, um ein Vermögen zu machen; wir ahnten nicht, welche Gefahren es birgt, einen Taler zu verdienen!",
    ["Bibbly thinks he is the only goblin in Desolace who knows how to make money. Well, the only caravan brave enough to travel these parts relies on me."] = "Bibbly glaubt, er sei der einzige Goblin in Desolace, der weiß, wie man Geld verdient. Nun, die einzige Karawane, die mutig genug ist, diese Gegenden zu bereisen, verlässt sich auf mich.",
    ["While I do possess much knowledge about the owlbeasts you defeated in Winterspring, I am not very learned on the subject of the magics they wield."] = "Obwohl ich viel Wissen über die Eulenbestien besitze, die Ihr in Winterquell besiegt habt, bin ich nicht sehr bewandert in den Magien, die sie führen.",
    ["Mirah Chandler's song, given for finishing a chain of favours in the Barrens -- the reward players remember long after they forget the errands."] = "Mirah Chandlers Lied, gegeben für das Abschließen einer Kette von Gefälligkeiten im Brachland – die Belohnung, an die sich Spieler noch lange erinnern, nachdem sie die Besorgungen vergessen haben.",
    ["Kill me. Before it's too late. I am Hameya. While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed. We are infected."] = "Tötet mich. Bevor es zu spät ist. Ich bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Brüder und ich schlechtes Fleisch ... und wir veränderten uns. Wir sind infiziert.",
    ["The black dragonflight's overseer in Lower Blackrock Spire, keeping the orcs there in line on Nefarian's behalf."] = "Der Aufseher des schwarzen Drachenschwarms in der Unteren Schwarzfelsspitze, der dort für Nefarian die Orcs in Schach hält.",
    ["Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge."] = "Demetria ist die oberste Beraterin des Großen Kreuzfahrers. Wegen ihrer „überirdischen“ Sinne wird sie das Orakel genannt. Sie hat dem Kreuzzug bei mehreren seiner Siege gegen die Geißel erfolgreich geholfen.",
    ["you are a hunter worthy of our company. From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated."] = "Ihr seid ein Jäger, würdig unserer Gesellschaft. Von den Schlachtfeldern Lordaerons bis zum tiefsten Dschungel habe ich selten solche Waffenkunst erlebt wie die, die Ihr bewiesen habt.",
    ["One of Onyxia's own teeth, taken after she was finally dragged out of Stormwind's court and killed in her lair."] = "Einer von Onyxias eigenen Zähnen, genommen, nachdem sie endlich aus dem Hof von Sturmwind gezerrt und in ihrem Unterschlupf getötet wurde.",
    ["A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."] = "Ein Leutnant des Ragnaros, der umgeben von seinen Feuergeschworenen kämpft und stärker wird, jedes Mal wenn einer von ihnen fällt.",
    ["I'm going to have to do something about the giants if I stay out here! They're certainly not good for business, now are they?"] = "Ich werde etwas gegen die Riesen unternehmen müssen, wenn ich hier draußen bleibe! Gut fürs Geschäft sind sie jedenfalls nicht, oder?",
    ["Wouldn't ye know it, every time ol' Hansel wants to take a moment to relax and reflect upon his life, the powers that be give him another job."] = "Wisst Ihr was, jedes Mal, wenn der alte Hansel einen Moment zum Entspannen und Nachdenken über sein Leben haben will, geben ihm die da oben einen neuen Job.",
    ["One of Nefarian's three guardian drakes, holding the suspended walkways above the lair floor."] = "Einer von Nefarians drei Wächterdrachen, der die hängenden Stege über dem Boden des Unterschlupfs hält.",
    ["We Zandalar prize what we wear as a symbol of accomplishment."] = "Wir Zandalar schätzen, was wir tragen, als Symbol von Errungenschaften.",
    ["You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators."] = "Ihr müsst beides meistern, um irgendeine Chance auf Erfolg in Zul'Gurub zu haben ... und irgendeine Chance, den Zandalar-Raubtieren zu gleichen.",
    ["In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe."] = "In den dunklen Zeiten nach dem Fall des Gurubashi-Imperiums nutzten die Zandalar-Raubtiere ihr Können, um den Stamm zu ernähren.",
    ["To Whom It May Concern: If you're reading this, I'm either dead or soon to be dead. It's hard to say. Most of the crew is dead anyhow. Found information about a Titan."] = "An alle, die es betrifft: Wenn Ihr dies lest, bin ich entweder tot oder bald tot. Schwer zu sagen. Der Großteil der Mannschaft ist sowieso tot. Habe Informationen über einen Titanen gefunden.",
    ["We have not sat idly by for a millennium. We have watched these beasts feast on their own when they have exhausted their utility. We have listened as they have plotted and schemed to destroy our world."] = "Wir haben nicht tatenlos ein Jahrtausend lang zugesehen. Wir haben beobachtet, wie diese Bestien ihresgleichen verschlingen, wenn sie ihren Nutzen erschöpft haben. Wir haben gehört, wie sie planten und Ränke schmiedeten, um unsere Welt zu zerstören.",
    ["Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."] = "Die Magie der Qiraji ist stark und uralt. Die mächtigsten Qiraji führen Gegenstände von solcher Macht, dass sie selbst einen Drachen innehalten lassen.",
    ["Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"] = "Bringt mir die Fesseln, die die höchsten Qiraji-Anführer tragen, und ich forme sie zu einem Satz Schulterstücke, furchtbarer noch als die Flügel Nefarians selbst!",
    ["Bring me a sample of his skin along with other minor components and I shall craft you leggings of great power."] = "Bringt mir eine Probe seiner Haut zusammen mit anderen kleineren Bestandteilen, und ich fertige Euch Beinschutz von großer Macht.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me an ordinary belt and a set of gloves that you wish to upgrade."] = "Ich glaube, eine Belohnung ist angebracht, wenn ich Euch weiter dafür interessieren will, meine Haut zu retten. Bringt mir einen gewöhnlichen Gürtel und ein Paar Handschuhe, die Ihr verbessern möchtet.",
    ["I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas."] = "Ich habe eine Verwendung für den Panzer des Gruftunholds entdeckt. Ich kann eine äußerst leichte und sehr tödliche Rüstung herstellen, indem ich die Fragmente mit einigen der entweihten magischen Rüstungen kombiniere, die in Naxxramas verloren gingen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icy Scale breastplate."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun einen Eisschuppen-Brustpanzer herstellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icy Scale bracers."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun Eisschuppen-Armschienen herstellen.",
    ["Stormwind has abandoned us. A foul wind of depravity rustles through the plains of Westfall. This was my homeland and I will not turn my back on the citizens who choose to remain here."] = "Sturmwind hat uns im Stich gelassen. Ein übler Wind der Verderbtheit weht durch die Ebenen von Westfall. Dies war meine Heimat, und ich werde den Bürgern, die hier bleiben wollen, nicht den Rücken kehren.",
    ["The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods."] = "Die Defias-Bande in Nordhain trägt Jutemasken, aber die Defias in Elwynn tragen Leinen, das ich zur Herstellung feiner Leinenwaren verwenden kann.",
    ["If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom! Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me."] = "Wenn der „Sammler“ Gold aus unseren Minen nimmt, dann bestiehlt er das Königreich! Bringt den Sammler vor Gericht und bringt mir den Ring, der in dem Abholplan erwähnt wird, den Ihr mir gegeben habt.",
    ["Help me make some Westfall Stew! Come back with the following ingredients: 3 Stringy Vulture Meat 3 Goretusk Snouts 3 Murloc Eyes 3 Okra"] = "Helft mir, einen Westfall-Eintopf zu kochen! Kommt mit folgenden Zutaten zurück: 3 zähe Geierfleisch, 3 Bluthauer-Schnauzen, 3 Murlocaugen, 3 Okra",
    ["Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest. A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder."] = "Gnolle, brutale Kreaturen, die in diesen Landen nichts Anständiges zu schaffen haben, wurden an den Grenzen des Elwynnwalds gesehen. Ein großes Rudel von ihnen, viel mehr, als wir allein bewältigen können, hat die Wälder südlich des Wachturms dort drüben befallen.",
    ["I'm behind on my report, and could use your help. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in."] = "Ich hinke mit meinem Bericht hinterher und könnte Eure Hilfe gebrauchen. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich sah so viele Trolle, dass ich Angst hatte, hineinzugehen.",
    ["You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."] = "Ihr habt den Verlassenen unter normalen Umständen Euer Potenzial gezeigt – nun wollen wir Euch unter Druck sehen. Die Klapperkäfig-Skelette, weitere willenlose Diener des Lichkönigs, sind ein härterer Gegner als die Zombies, denen Ihr Euch bisher gestellt habt.",
    ["We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres."] = "Wir Verlassenen befinden uns im Krieg mit der Armee der Geißel des Lichkönigs: nekromantisch erweckte Armeen der Untoten, üble Bestien des Nordens und gequälte Geister.",
    ["Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell."] = "Berichte meiner Vorgesetzten in Brill deuten darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Totenglocke geschickt wurde.",
    ["While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims."] = "Während Ihr unterwegs wart, um zu sammeln, entdeckte ich in einem meiner Wälzer einen alten Text, der darauf hinweist, dass eine uralte Seuche Tausende unschuldiger Opfer dahinraffte.",
    ["The Scourge are trying to form a base at the Agamand Mills. If they do, then they can stage further attacks within Tirisfal. The orders have been given."] = "Die Geißel versucht, einen Stützpunkt bei den Agamand-Mühlen zu errichten. Wenn ihr das gelingt, kann sie von dort weitere Angriffe innerhalb von Tirisfal führen. Die Befehle sind erteilt.",
    ["The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn. Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well."] = "Die Armee von Sturmwind hat ein Kopfgeld auf Murloc-Lauerer und -Sammler in Elwynn ausgesetzt. Schlachtet sie und bringt mir ihre zerrissenen Murlocflossen, und die Armee von Sturmwind wird Euch gut belohnen.",
    ["I was sent to the Valley to guide you, but I have discovered a growing taint here... A group that calls itself the Burning Blade has a coven here in the Valley of Trials."] = "Ich wurde in das Tal geschickt, um Euch zu führen, aber ich habe hier eine wachsende Besudelung entdeckt ... Eine Gruppe, die sich die Brennende Klinge nennt, hat hier im Tal der Prüfungen einen Zirkel.",
    ["The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach."] = "Das Fell der Säbelzahnkatze hat eine unverkennbare graue Farbe, die mit dem umliegenden Wald verschmilzt. Wie sie so daliegt, erkennt Ihr, dass sie schwer verwundet ist, mit tiefen Rissen über Rücken und Bauch.",
    ["There is a malevolence growing in the timberlings. We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help."] = "In den Holzlingen wächst eine Bosheit. Wir versuchen, die Quelle zu finden, aber bis dahin ... müssen wir, um Teldrassil sicher zu halten, die Holzlinge fällen, denen nicht mehr zu helfen ist.",
    ["I trust the Valley of Trials will teach you much, young. I was sent to the Valley to guide you, but I have discovered a growing taint here..."] = "Ich vertraue darauf, dass das Tal der Prüfungen Euch viel lehren wird, Junger. Ich wurde in das Tal geschickt, um Euch zu führen, aber ich habe hier eine wachsende Besudelung entdeckt ...",
    ["I had a month's worth of dried meats salted and locked away for the cold season. Kept it locked so the bears wouldn't get it! But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker."] = "Ich hatte Dörrfleisch für einen ganzen Monat eingesalzen und für die kalte Jahreszeit weggesperrt. Hielt es verschlossen, damit die Bären es nicht bekommen! Aber während ich Hirsche jagte, hat dieses Biest, Old Icebeard, den Fleischschrank mitgenommen.",
    ["Teebu's blade sets things on fire for reasons no one has ever explained. It is famous for being almost useless and deeply desirable at the same time."] = "Teebus Klinge setzt Dinge in Brand, aus Gründen, die nie jemand erklärt hat. Sie ist berühmt dafür, fast nutzlos und zugleich zutiefst begehrenswert zu sein.",
    ["By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate."] = "Auf Befehl von Hochexekutorin Darthalia wird der Mensch namens Baron Vardus wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekanntermaßen ein hochrangiges Mitglied der Organisation, die als das Syndikat bekannt ist.",
    ["Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields."] = "Unsere ersten Spähberichte aus Silberwald zeigen, dass die Morschhäute einen Stützpunkt auf einer alten Farm im Norden haben, den Toten Feldern.",
    ["You looking fer work? I might have some if you're up for a little challenge. I got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed."] = "Sucht Ihr Arbeit? Ich hätte vielleicht welche, wenn Ihr für eine kleine Herausforderung zu haben bist. Ich hab 'nen Freund namens Groy, der ein Vermögen macht mit dem Verkauf von dem, was die Naga Akiris-Schilf nennen: eine Art wertvolles Meeresschilf.",
    ["But the power harnessed in these goggles will allow you to locate them easily. A little gnomish ingenuity goes a long way!"] = "Aber die Kraft, die in dieser Schutzbrille gebündelt ist, wird Euch erlauben, sie mühelos aufzuspüren. Ein bisschen gnomischer Erfindungsreichtum reicht weit!",
    ["Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses... Go into the Ruins of Alterac and seek out the Crushridge Warmongers."] = "Nun, da Ihr einen Vorgeschmack auf die Crushridge-Oger bekommen habt, möchte ich, dass Ihr ihnen richtig die Nasen blutig schlagt ... Geht in die Ruinen von Alterac und sucht die Crushridge-Kriegstreiber.",
    ["I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud."] = "Ich habe Berichte erhalten, dass sich eine Gruppe Untoter verschanzt, um einen Angriff gegen uns vorzubereiten. Mit dieser Information können wir den Spieß umdrehen und sie zuerst angreifen, um ihren kleinen Plan im Keim zu ersticken.",
    ["Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co."] = "Reisende fragen mich ständig nach dem Steinkrallengebirge. Es scheint ein beliebter Ort für Abenteuer zu sein – egal, ob Ihr Windreiter, Elementare sucht oder Geschäfte mit der Venture Co. habt.",
    ["Indurium has an amazing resistance to heat! I'm sure it will work for Fizzle's pistons."] = "Indurium hat eine erstaunliche Hitzebeständigkeit! Ich bin sicher, es wird für Fizzles Kolben funktionieren.",
    ["You have done well. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles."] = "Ihr habt Eure Sache gut gemacht. Ihr habt meine Prüfung bestanden und die Prüfungen vor meiner. Kehrt zu Dorn in Tausend Nadeln zurück.",
    ["Strength has left me. Your help is needed! Long ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well."] = "Die Kraft hat mich verlassen. Eure Hilfe wird gebraucht! Vor langer Zeit war dieser Ort ein großer Tempel der Elune. Doch Unglück führte zum Verfall, als die Verderbnis eines Alten Gottes aus der Tiefe der Erde emporsickerte und den heiligen Mondbrunnen befleckte.",
    ["We mages do more than just waggle our fingers and make pretty sparks! We control magic, the base fabric of our world! And that takes great care, and resolve."] = "Wir Magier tun mehr, als nur mit den Fingern zu wackeln und hübsche Funken zu sprühen! Wir beherrschen die Magie, das Grundgewebe unserer Welt! Und das erfordert große Sorgfalt und Entschlossenheit.",
    ["This world has been victim to massive mystic struggles, which tore magic currents from once stable channels. We struggle to determine the effects these changes have caused, and some of us fear the worst!"] = "Diese Welt wurde Opfer gewaltiger mystischer Kämpfe, die magische Strömungen aus einst stabilen Bahnen rissen. Wir bemühen uns, die Auswirkungen dieser Veränderungen zu bestimmen, und manche von uns fürchten das Schlimmste!",
    ["I'll go make the wands now."] = "Ich gehe jetzt die Zauberstäbe machen.",
    ["Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help. Deep in the Deadmines is a functional goblin shredder."] = "Gnomeregan ist unter die Kontrolle dieser niederträchtigen Troggs gefallen! Die Lage ist ernst, aber vielleicht könnt Ihr helfen. Tief in den Todesminen steht ein funktionstüchtiger Goblin-Schredder.",
    ["Naralex had a noble goal. Our great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was."] = "Naralex hatte ein edles Ziel. Unser großer Anführer strebte danach, den Smaragdgrünen Traum zu betreten und zu helfen, dieses raue Land wieder zu dem üppigen Wald heranwachsen zu lassen, der es einst war.",
    ["The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade."] = "In dem Moment, da das Artefakt vom Monolithen entfernt wird, spürt Ihr, wie die Energie im Stab von Equinex zu schwinden beginnt.",
    ["Oh, you know what? That reminds me. You wanna finish up a little job I took up while I was in Tanaris? It's easy... Krinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places."] = "Oh, wisst Ihr was? Das erinnert mich an etwas. Wollt Ihr eine kleine Arbeit zu Ende bringen, die ich in Tanaris angenommen hatte? Sie ist einfach ... Krinkle Goodsteel in Gadgetzan suchte nach Zeug, das man hier in der Sengenden Schlucht und an ein paar anderen Orten findet.",
    ["Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil. Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine."] = "Vor der Küste der Dunkelküste, nördlich von uns, liegen zwei Schiffswracks – die Silver Dawning und der Mist Veil. Vor einiger Zeit gerieten beide Schiffe an die verdammten Murlocs, als sie über das weite Meer nach Auberdine segelten.",
    ["A human lord who traded his life for undeath and became a lich in Scholomance. Killing him takes a blade specifically made to sever the bargain."] = "Ein menschlicher Lord, der sein Leben gegen die Untotheit eintauschte und in Scholomance zum Lich wurde. Ihn zu töten erfordert eine Klinge, die eigens dafür gemacht wurde, den Handel zu zerschneiden.",
    ["Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures."] = "Rackmores Logbuch berichtet, wie sein Schiff auf dem Weg zur Feste Mondfeder von Meereskreaturen angegriffen wurde.",
    ["The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx. Throughout Jintha'alor you will find dark vessels of tainted blood."] = "Die Vilebranch kämpfen mit übernatürlicher Wildheit. Das liegt an den üblen magischen Gespinsten der üblen Priesterin Hexx. In ganz Jintha'alor findet Ihr dunkle Gefäße verdorbenen Blutes.",
    ["How can one truly hope to win against a foe that is not even really there? We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe."] = "Wie kann man wirklich hoffen, gegen einen Feind zu gewinnen, der nicht einmal wirklich da ist? Wir Zandalar kennen die Macht davon, und deshalb haben Illusionisten einen Ehrenplatz im Stamm.",
    ["For you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power. For this, I will give you arm wraps our illusionists use to weave their spells."] = "Um den Weg unserer Illusionisten zu erfahren, geht nach Zul'Gurub und bringt mir ausgewählte Vorbilder der Macht. Dafür gebe ich Euch Armwickel, die unsere Illusionisten benutzen, um ihre Zauber zu weben.",
    ["Legend states that their ancient robes never looked the same twice. I will give you an illusionist's robe..."] = "Der Legende nach sahen ihre uralten Roben nie zweimal gleich aus. Ich werde Euch eine Illusionistenrobe geben ...",
    ["There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole."] = "Tief im versunkenen Tempel von Atal'Hakkar lebt ein grüner Drache namens Morphaz. Vor Jahren überwältigte er mich in einem kühnen Hinterhalt und verschlang meinen Lehrling im Ganzen.",
    ["I can make you a protective item that'll be of assistance in the fight against our enemy. I shall need a Qiraji drape, which I'll resize for you of course."] = "Ich kann Euch einen Schutzgegenstand anfertigen, der im Kampf gegen unseren Feind hilfreich sein wird. Dazu brauche ich einen Qiraji-Umhang, den ich für Euch natürlich in der Größe anpasse.",
    ["Well met. I've something that might interest you. I have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality."] = "Seid gegrüßt. Ich habe etwas, das Euch interessieren könnte. Ich besitze eine Rüstung, ähnlich der, die Leute Eures Berufs tragen, aber von weit höherer Qualität.",
    ["While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire."] = "Während der Großteil der Bücher – um es unverblümt zu sagen – Geschwätz enthielt, gab es einige Perlen. Einer dieser Wälzer dokumentierte die Herstellung eines Rüstungssatzes, der eines Erzmagiers würdig ist: Frostfeuer.",
    ["Now that my crop is saved, take this Grape Manifest to Brother Neals. He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes."] = "Nun, da meine Ernte gerettet ist, nehmt dieses Traubenverzeichnis und bringt es zu Bruder Neals. Er verwaltet den Nahrungs- und Getränkevorrat in Nordhain, und ich bin sicher, er wird sich freuen zu hören, dass er frische Trauben hat.",
    ["My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills."] = "Mein Freund und Kollege als Belagerungsmaschinen-Pilot, Mori Hildelve, ist in den Hügeln verschollen.",
    ["After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache."] = "Nachdem Ihr die Karte sorgfältig geprüft habt, begreift Ihr, dass es sich bei Eurem Fund um die Pläne handelt, die der Kriegshäuptling der Borstennacken für eine ausgedehnte Belagerung des Lagers Narache gemacht hat.",
    ["My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite."] = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen mit einem Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, den rasiermesserscharfen Klauen und dem giftigen Biss.",
    ["Take this Nether Gem to my old comrade Bethor. It will let us communicate... and I have much to tell him."] = "Bringt diesen Nethersplitter zu meinem alten Kameraden Bethor. Er wird uns ermöglichen, zu kommunizieren ... und ich habe ihm viel zu erzählen.",
    ["you are a with proven interest in the security of Northshire. You are now tasked with the protection of the surrounding Elwynn Forest."] = "Ihr habt ein erwiesenes Interesse an der Sicherheit von Nordhain gezeigt. Euch obliegt nun der Schutz des umliegenden Elwynnwalds.",
    ["He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."] = "Er hat alle Versuche, ihn zu fassen, vereitelt. Die Armee von Sturmwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt.",
    ["Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat."] = "Mancher Jäger wird von Loch Modan angezogen, um unsere berühmten Krokilisken zu jagen. Es gibt immer Händler, die Krokiliskenhäute für Kleidung oder Rüstungen suchen, und manche mögen auch den Geschmack ihres Fleisches.",
    ["Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed. Aye, the Dark Iron dwarves are a devilish breed."] = "Viele meiner Soldaten starben in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über die Thandol-Überspannung zerstört wurde. Ja, die Dunkeleisenzwerge sind ein teuflisches Volk.",
    ["Hail. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire."] = "Seid gegrüßt. Habt Ihr vielleicht die Spinnen gesehen, die die Westgrenze übernommen haben? Die achtbeinigen Plagen sind zu viel für uns, und der Kommandant hat nicht genug Männer übrig, so weit weg von Dunkelhain.",
    ["My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga."] = "Mein früherer Mentor bei der Stadtwache von Sturmwind schickte mir eine Nachricht, dass das Oberkommando der Allianz sich wegen der Bedrohung durch die Naga Sorgen macht.",
    ["But complications have arisen. A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol."] = "Aber es sind Komplikationen aufgetreten. Eine örtliche Bande von Ogern hat die Mizjah-Ruinen südöstlich von Grom'gol besetzt.",
    ["I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain."] = "Ich setze mein Vertrauen in Euch und in jeden, den Ihr aufbringen könnt, um mir zur Freiheit zu verhelfen. Der große Himmelsmähnen-König Mukla ist mein Kerkermeister. Er befehligt die Bestien dieser Insel, und sie halten mich mithilfe dieser Kette gegen meinen Willen hier.",
    ["Curses! That swab Maury put a lock on his foot, and I can't open it! His loot's inside the foot, and that's what he owes me! We need to find the key to open the lock."] = "Verflucht! Dieser Schwabber Maury hat ein Schloss an seinen Fuß gemacht, und ich kann es nicht öffnen! Seine Beute ist im Fuß, und das ist es, was er mir schuldet! Wir müssen den Schlüssel finden, um das Schloss zu öffnen.",
    ["Blast the nerve of Firallon! He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us. The Bloodsail Buccaneers will pay for their carelessness."] = "Verdammt sei die Frechheit von Firallon! Er könnte nicht einmal eine Jolle über den Kristallsee steuern, geschweige denn eine ganze Flotte gegen uns führen. Die Blutsegelbukaniere werden für ihre Nachlässigkeit bezahlen.",
    ["The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released."] = "Das Licht schwindet langsam, das Schwert Trol'kalar, gehalten in einer Steinscheide, wurde freigegeben.",
    ["O'Breen led the ships into the cove. We were certain this is where the treasure could be found. The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower."] = "O'Breen führte die Schiffe in die Bucht. Wir waren sicher, dass hier der Schatz zu finden war. Die Harbinger legte sicher an, doch als die Maiden's Folly und der Spirit of Silverpine sich näherten, begannen die Gezeiten zu sinken.",
    ["The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily."] = "Der Schatz liegt schon so lange auf dem Meeresgrund, dass die Edelsteine zu dickem Stein verkalkt sind. Aber die Kraft, die in dieser Schutzbrille gebündelt ist, wird Euch erlauben, sie mühelos aufzuspüren.",
    ["It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal."] = "Es wird hier schwierig, wenn ich es nicht schaffe, ein paar Materialien zum Bau von Verteidigungsanlagen und anderen Notwendigkeiten zusammenzukratzen. Mir ist aufgefallen, dass die Oger in der Gegend gut mit Altmetall ausgestattet zu sein scheinen.",
    ["The Syndicate in Stromgarde do battle with our contingent of militia there."] = "Das Syndikat in Stromgarde liefert sich Kämpfe mit unserem Milizkontingent dort.",
    ["I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again."] = "Ich glaube, ich sollte auch daran denken, von hier zu verschwinden. Es wird nicht lange dauern, bis sich die Nachricht von dem, was hier geschehen ist, bei den Oberen verbreitet, und ich bin sicher, sie wären nicht gerade erfreut, mir erneut zu begegnen.",
    ["The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken. Far south of the Barrens lies a land known as Thousand Needles."] = "Die Blutfurien wurden unterworfen. Aber sie werden sich bald wieder sammeln, wenn nichts unternommen wird. Weit südlich des Brachlands liegt ein Land namens Tausend Nadeln.",
    ["Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own."] = "Delgren hat mich gebeten, Nachrichten und Vorräte zu Schildwache Starbreeze nach Auberdine zu bringen, aber ich scheue davor zurück, allein aufzubrechen.",
    ["Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals."] = "Obwohl ich nichts von diesem Lord Azrethoc weiß, stimme ich Maurin zu: Er muss aufgehalten werden; besonders, wenn er versucht, Einfluss auf die Brennende Klinge zu gewinnen, um seine Ziele voranzutreiben.",
    ["Please help! These creatures are going to eat me! Help me out of here, and I'll give you a great treasure! It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know."] = "Bitte helft! Diese Kreaturen werden mich fressen! Helft mir hier raus, und ich gebe Euch einen großen Schatz! Er liegt in meinem Lager im Sumpf nördlich von Steinard, aber er ist in einer verschlossenen Truhe, die man nur durch einen Trick öffnen kann, den ich allein kenne.",
    ["Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all."] = "Warum gehen wir nicht zur Schmiede hinüber und fangen damit an? Ich habe mich schon seit einiger Zeit auf Eure Ankunft vorbereitet, also dürfte es nicht lange dauern.",
    ["Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that. He'll send word to Ironforge to let my Jordan know that he has nothing to fear."] = "Bitte kehrt zu Duthorian zurück und lasst ihn wissen, dass ich vorerst in Sicherheit bin. Das habe ich Euch und der Kirche zu verdanken. Er wird Nachricht nach Eisenschmiede senden, damit mein Jordan weiß, dass er nichts zu befürchten hat.",
    ["Thanks again for your help. Here's a bottle of Steamwheedle bilge rum. Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze."] = "Nochmals danke für Eure Hilfe. Hier ist eine Flasche Dampfdruck-Bilgenrum. Bringt sie zu MacKinley, und er kann endlich seine verrückten Vorstellungen über den Schnaps von Beutebucht zu den Akten legen.",
    ["A plain plate glove that became famous for its random enchants -- the of Strength roll is a 7.9% chance and was worth chasing over guaranteed epics for years."] = "Ein schlichter Plattenhandschuh, der für seine zufälligen Verzauberungen berühmt wurde – der „der Stärke“-Wurf hat eine Chance von 7,9 % und war jahrelang die Jagd wert, statt garantierter Epics.",
    ["The gnome's voice crackles once again from the robot: \"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure."] = "Die Stimme des Gnoms knistert erneut aus dem Roboter: „Ich muss OOX-09/HL an einen offenen, sicheren Ort bringen, damit er ein langwieriges Startverfahren einleiten kann.",
    ["With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache. Perhaps he or someone there can make further sense of what the gnolls are up to."] = "Nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Swiftstrider im Lager Mojache zu bringen. Vielleicht kann er oder jemand dort mehr Sinn in das machen, was die Gnolle im Schilde führen.",
    ["Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home."] = "Während dieser feige Narr Mok'Morokk in Macht schwelgt und Tharg mit den Dämonen von Kummer und Rache ringt und um die Führung des Clans buhlt, scheine ich der Einzige zu sein, der sich darum kümmert, die Quelle der Aggression gegen unsere alte Heimat zu ermitteln.",
    ["What is left of a green dragon who went into the Sunken Temple after the Nightmare and did not come out himself."] = "Was von einem grünen Drachen übrig ist, der nach dem Albtraum in den Versunkenen Tempel ging und nicht selbst wieder herauskam.",
    ["I'll tell you what. If you give me those unfired gauntlets, I will teach you how to make a set all your own."] = "Ich sag Euch was. Wenn Ihr mir diese ungebrannten Stulpen gebt, bringe ich Euch bei, wie man einen ganz eigenen Satz herstellt.",
    ["For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become?"] = "So lange war ich eine Marionette des Großen Kreuzfahrers. Welchen Grund gab es, gegen das zu kämpfen, was der Scharlachrote Kreuzzug geworden war?",
    ["A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."] = "Ein Kernhund des tiefen Feuers, als Wachtier gehalten und von Ragnaros' Leutnants gefüttert.",
    ["Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere! I was able to gather most of the pages but many are still strewn about the jungle."] = "Alles lief gut, aber ein großer Windstoß fegte durch das Lager und verstreute die Seiten überall! Ich konnte die meisten Seiten einsammeln, aber viele liegen noch im Dschungel verstreut.",
    ["Unfortunately, I can't dish out the beats like I used to, due to this here fat finger problem. Ye see, the climate out here combined with the lack o' air pressure makes me fingers expand."] = "Leider kann ich die Beats nicht mehr so raushauen wie früher, wegen diesem Dickfinger-Problem. Seht Ihr, das Klima hier draußen in Verbindung mit dem fehlenden Luftdruck lässt meine Finger anschwellen.",
    ["Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."] = "Nefarians bestes Ergebnis: ein zweiköpfiger chromatischer Schrecken, der den Atem jedes Drachenschwarms zugleich in sich trägt.",
    ["They imbue their breastplates with powerful mojo. If their beliefs falter in the face of the enemy, their breastplate will not."] = "Sie erfüllen ihre Brustpanzer mit mächtigem Mojo. Wenn ihr Glaube angesichts des Feindes wankt, wird ihr Brustpanzer es nicht tun.",
    ["Your beliefs are alien to us, heathen. Ancient Zandalar were once branded as heretics."] = "Euer Glaube ist uns fremd, Heide. Die uralten Zandalar wurden einst als Ketzer gebrandmarkt.",
    ["Heathens have a place in the tribe. Heathens are freethinkers of Zandalar."] = "Heiden haben einen Platz im Stamm. Heiden sind die Freidenker von Zandalar.",
    ["One of Hakkar's high priests, who returns to his feet twice before he stays down."] = "Einer von Hakkars Hohepriestern, der zweimal wieder auf die Beine kommt, bevor er liegen bleibt.",
    ["A green dragon of Ysera's flight, turned by the Nightmare and hunted across Feralas ever since."] = "Ein grüner Drache aus Yseras Schwarm, vom Albtraum verdreht und seither quer durch Feralas gejagt.",
    ["The gems that adorn Qiraji idols would work quite well, as their quality is superior. Bring me the ring and idols and I'll create a powerful ring for you."] = "Die Edelsteine, die Qiraji-Götzen zieren, würden sich recht gut eignen, da ihre Qualität überlegen ist. Bringt mir den Ring und die Götzen, und ich fertige Euch einen mächtigen Ring.",
    ["I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gauntlets that you wish to upgrade."] = "Ich glaube, eine Belohnung ist angebracht, wenn ich Euch weiter dafür interessieren will, meine Haut zu retten. Bringt mir den Gürtel und das Paar Stulpen, die Ihr verbessern möchtet.",
    ["You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas."] = "Die Überreste unserer gefallenen Helden findet Ihr auf den Leichen der Lords von Naxxramas.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icy Scale gauntlets."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun Eisschuppen-Stulpen herstellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create an Icebane breastplate."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun einen Eisbann-Brustpanzer herstellen.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Icebane gauntlets."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun Eisbann-Stulpen herstellen.",
    ["Thanks to you and Omarion (May he rest in peace), I am now able to create Icebane bracers."] = "Dank Euch und Omarion (möge er in Frieden ruhen) kann ich nun Eisbann-Armschienen herstellen.",
    ["This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune."] = "Das wird sie wenigstens länger vor Schaden schützen, falls sie in Schwierigkeiten gerät. Kehrt hierher zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.",
    ["Normally I put forth a small challenge to followers of the Light to test their skill."] = "Normalerweise stelle ich den Anhängern des Lichts eine kleine Herausforderung, um ihr Können zu prüfen.",
    ["You be ready for your first test. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops."] = "Ihr sein bereit für Eure erste Prüfung. Südlich von Klingenhügel, gleich außerhalb der Stadt, einer unserer Grunzer verwundet, weil er kämpft gegen ein paar von Proudmoores alten Truppen.",
    ["Our power comes from darkness and shadow, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts."] = "Unsere Macht kommt aus Dunkelheit und Schatten, aber das ist nicht Eure einzige Rolle. Ihr habt anerkannt, dass es Verdienst hat, die Heilkunst zu kennen.",
    ["But to blow the horn, you need a mouthpiece. To get a mouthpiece, kill Maraudine centaur."] = "Aber um das Horn zu blasen, braucht Ihr ein Mundstück. Um ein Mundstück zu bekommen, tötet Maraudine-Zentauren.",
    ["You secure the sealed testing kit for the journey back to the Undercity. Apothecary Zinge waits for you and the sealed field testing kit there."] = "Ihr sichert das versiegelte Testset für die Rückreise zur Unterstadt. Apotheker Zinge wartet dort auf Euch und das versiegelte Feldtestset.",
    ["The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe."] = "Die Beichtväter der Zandalar tragen alle einen unverwechselbaren Umhang, der sie als Bewahrer des Stammes kennzeichnet.",
    ["Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe."] = "Kurz nach dem Fall der Gurubashi wären wir Zandalar beinahe einer letzten Niederlage durch das Böse im eigenen Stamm erlegen.",
    ["We Zandalar invest power in those who speak with the authority of divinity."] = "Wir Zandalar verleihen Macht denen, die mit der Autorität der Göttlichkeit sprechen.",
    ["The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity. Bring me the desecrated remnants of the departed along with reagents of purification and you shall know faith."] = "Die armen Seelen, deren letzte Atemzüge auf dem Schlachtfeld getan wurden – ihrer selbst ihrer Würde beraubt. Bringt mir die entweihten Überreste der Dahingegangenen zusammen mit Reagenzien der Läuterung, und Ihr werdet den Glauben kennenlernen.",
    ["I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave."] = "Ich kam nach Schattenglen, um die Webwood-Spinnen zu beobachten, die in der Schattenfadenhöhle hausen.",
    ["I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key."] = "Ich überlasse es Euch, Tazans Satteltasche zu öffnen und mit ihrem Inhalt zu mir zurückzukehren. Der Schließmechanismus ist kompliziert, daher wäre es wohl am einfachsten, wenn Ihr den Schlüssel beschafft.",
    ["The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel."] = "Die geschätzte Tunika der Zandalar-Tollköpfe ist keine Ausnahme und strahlt die rohe Macht von Chaos und Wahnsinn aus, die sie kanalisieren können.",
    ["One of Zandalar's legendary madcaps was Khar'vaxal the Cracked."] = "Einer der legendären Tollköpfe von Zandalar war Khar'vaxal der Verrückte.",
    ["The madcaps of Zandalar are similar to rogues, but above all else they embrace madness..."] = "Die Tollköpfe von Zandalar ähneln Schurken, aber vor allem anderen umarmen sie den Wahnsinn ...",
    ["The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."] = "Der Seelenschinder, ein Blutgott, den die Atal'ai-Priester nach Zul'Gurub beschworen. Er nährt sich vom Blut seiner eigenen Anbeter, womit sie nicht gerechnet hatten.",
    ["The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."] = "Die mächtigsten Qiraji führen Gegenstände von solcher Macht, dass sie selbst einen Drachen innehalten lassen. Bringt mir die Qiraji-Fesseln des Befehls und andere kleinere Bestandteile, und ich fertige Euch ein Paar mächtige Stiefel.",
    ["If you want Bonescythe made, you're going to have to supply the materials."] = "Wenn Ihr Knochensense gefertigt haben wollt, müsst Ihr die Materialien beschaffen.",
    ["Death Knight Darkreaver lords over the Great Ossuary in the Scholomance. He threatens to twist the spirit realm to do his own bidding, and he must be stopped!"] = "Todesritter Darkreaver gebietet über das Große Ossarium in Scholomance. Er droht, das Geisterreich nach seinem Willen zu verdrehen, und muss aufgehalten werden!",
    ["The augurs of the Zandalar all wear a distinctive chest piece called a hauberk."] = "Die Auguren der Zandalar tragen alle ein unverwechselbares Brustteil, das Kettenhemd genannt wird.",
    ["Bring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us. Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!"] = "Bringt mir ein Opfer der Vorbilder der Macht aus Zul'Gurub und beweist Euch vor uns. Tut es, und ich geb Euch einen Gürtel, den unsere Auguren benutzen – einen mit mächtigem Mojo drin!",
    ["They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people. As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe."] = "Sie sind keine Hexendoktoren; sie verbringen ihre Zeit damit, Knochen zu werfen oder in Blättern zu lesen, um Einsicht zu gewinnen – nicht, um Leute zu verhexen. Als Schamane wisst Ihr schon etwas über die Macht der Weissagung; wir Zandalar schätzen die Einsicht, die sie dem Stamm gibt.",
    ["Hail! I can tell by your demeanor that you've seen and done much in this world. Yet I'm willing to wager you haven't seen a piece of armor like this."] = "Heil! Ich sehe an Eurer Haltung, dass Ihr in dieser Welt schon viel gesehen und getan habt. Doch ich bin bereit zu wetten, dass Ihr noch kein Rüstungsteil wie dieses gesehen habt.",
    ["Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the amulet back together."] = "Valthalaks Seele wurde in diesem Amulett aufbewahrt. In unserer Gier teilten wir es töricht in drei Teile, ohne den Fluch zu kennen, der uns erwartete. Der einzige Weg, Valthalaks Zauber zu stoppen, ist, das Amulett wieder zusammenzusetzen.",
    ["A truly amazing story! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past."] = "Eine wahrhaft erstaunliche Geschichte! Ihr habt meinen Dank und die herzliche Dankbarkeit aller Beteiligten, das versichere ich Euch. Durch Eure Bemühungen sind wir von den Fehlern unserer Vergangenheit erlöst.",
    ["You've proven to be a very reliable individual. As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance."] = "Ihr habt Euch als sehr zuverlässig erwiesen. So sehr ich darauf vertraue, dass Ihr mir durch diese Zwangslage helft, wäre es klug von mir, Euch entsprechend Eurer Leistung zu belohnen.",
    ["For now I will exchange your belt and gauntlets."] = "Fürs Erste tausche ich Euren Gürtel und Eure Stulpen ein.",
    ["Bring me the remnants of the fallen along with purification materials and Earthshatter shall be yours to don."] = "Bringt mir die Überreste der Gefallenen zusammen mit Läuterungsmaterialien, und Erdsplitter soll Euch gehören.",
    ["Thanks to you and Omarion, may he rest in peace, I am now able to create Glacial gloves."] = "Dank Euch und Omarion, möge er in Frieden ruhen, kann ich nun Gletscherhandschuhe herstellen.",
    ["I hear Lord Wishock enjoyed his beverage. You have served us well. The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you."] = "Ich höre, Lord Wishock hat sein Getränk genossen. Ihr habt uns gut gedient. Die Hexenmeister von Sturmwind werden dank Euch ungestört unsere Wege praktizieren können.",
    ["Even fragmented, they still possess the powers of the demons trapped inside. The orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps."] = "Selbst zersplittert besitzen sie noch immer die Kräfte der darin gefangenen Dämonen. Die Kugel von Soran'ruk wurde in zwei Teile zerbrochen, einer wurde weiter zerbrochen, damit ihn die Akolythen des Zwielichthammers in der Tiefschwarzen Grotte benutzen konnten.",
    ["I will put the robe together for you now. It will take but a few moments. Do not go far."] = "Ich werde die Robe jetzt für Euch zusammensetzen. Es dauert nur einen Augenblick. Geht nicht weit.",
    ["I will get started immediately on crafting your orb and infusing your new demon into it. When done, you will have the choice of having it in the form of a staff or orb."] = "Ich werde sofort damit beginnen, Eure Kugel herzustellen und Euren neuen Dämon in sie zu fassen. Wenn ich fertig bin, habt Ihr die Wahl, sie als Stab oder als Kugel zu erhalten.",
    ["I am the only survivor from our caravan attack by the centaur! A rare yet mighty panther is guarding my best gizmo, which is around his neck."] = "Ich bin der einzige Überlebende unserer Karawane, die von den Zentauren angegriffen wurde! Ein seltener, aber mächtiger Panther bewacht mein bestes Spielzeug, das er um den Hals trägt.",
    ["The prison is ready. Now for the most difficult portion of this task. You must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison."] = "Das Gefängnis ist bereit. Nun zum schwierigsten Teil dieser Aufgabe. Ihr müsst mit diesem Kristallgefängnis einen Verdammniswachen-Kommandanten in der Verdorbenen Narbe finden und fangen.",
    ["Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal."] = "Kroshius liegt als Haufen im Nordosten, im Splitternarbental. Nehmt dieses Teufelsfeuer und benutzt es auf seinen Überresten. Das Feuer sollte den gefallenen Höllenbestien wiedererwecken.",
    ["Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further. Through an ancient and arcane ritual, they allow a demon to enter their being."] = "Hexenmeister betreten gefährliches Terrain im Umgang mit Dämonen, aber unsere Demoniker gehen noch einen Schritt weiter. Durch ein uraltes, arkanes Ritual lassen sie einen Dämon in ihr Wesen eindringen.",
    ["The demoniac seeks to embody power outright, not just possess it."] = "Der Demoniker strebt danach, Macht geradezu zu verkörpern, nicht nur, sie zu besitzen.",
    ["The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric."] = "Das ultimative Symbol der Macht im Stamm ist die Gewandung, die wir in der Schlacht tragen. Die Roben eines Demonikers haben feinen Runenstoff und verheerend mächtiges Mojo zu einem einzigen Gewebe verschmolzen.",
    ["My pet is almost done. Now I just need something to stuff it with. Only the voodoo feathers from the trolls in the sunken temple will do. They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro."] = "Mein Haustier ist fast fertig. Jetzt brauche ich nur noch etwas, womit ich es ausstopfen kann. Nur die Voodoo-Federn der Trolle im Versunkenen Tempel kommen infrage. Sie hören auf die Namen Gasher, Mijan, Zolo, Hukku, Zul'lor und Loro.",
    ["I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us."] = "Ich mache keine Ausflüchte, Made. Die Dunkelheit, die die Gegenstände des Seuchenherzens in sich tragen, könnte uns beide durchaus vernichten.",
    ["Hey. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan. They just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe."] = "Hey. Seid vorsichtig hier. Überall sind Dunkeleisenzwerge – sahen aus wie der Schattenschmiede-Clan. Sie haben gerade die Ausgrabungsstätte angegriffen, an der ich arbeitete – haben fast alle dort getötet, auch meinen Chef Hammertoe.",
    ["Talk to my friend, Furen Longbeard, in the Dwarven District of Stormwind. He's the best shieldsmith you'll ever meet, and he owes me a big favor."] = "Sprecht mit meinem Freund Furen Longbeard im Zwergenviertel von Sturmwind. Er ist der beste Schildschmied, den Ihr je treffen werdet, und er schuldet mir einen großen Gefallen.",
    ["The Whirlwind Axe comes from an elemental trial a warrior has to complete alone. Three weapons come from the same chain and you keep only one."] = "Die Wirbelwindaxt stammt aus einer Elementarprüfung, die ein Krieger allein bestehen muss. Drei Waffen stammen aus derselben Kette, und man behält nur eine.",
    ["One of three weapons from the same solitary warrior trial. Choosing it means giving up the axe and the staff for good."] = "Eine von drei Waffen aus derselben einsamen Kriegerprüfung. Sie zu wählen bedeutet, die Axt und den Stab für immer aufzugeben.",
    ["Burlguard sent you, did he? Yes, I have spare weapons around here, but first I have a task for you... A while ago a Defias villain Dead-tooth Jack tricked me."] = "Burlguard hat Euch geschickt, ja? Ja, ich habe hier ein paar Ersatzwaffen, aber zuerst habe ich eine Aufgabe für Euch ... Vor einer Weile hat mich ein Defias-Schurke, Dead-tooth Jack, hereingelegt.",
    ["To pass this trial, you must travel south to the Field of Giants. There you will find a host of crawling, insect creatures. They are new to the Barrens and I do not like what they herald."] = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr eine Horde kriechender, insektenartiger Kreaturen. Sie sind neu im Brachland, und mir gefällt nicht, was sie ankündigen.",
    ["I will give you a weapon, but first you must aid me. The Razormanes to the northwest came into my camp a few nights past."] = "Ich werde Euch eine Waffe geben, aber zuerst müsst Ihr mir helfen. Die Razormane aus dem Nordwesten kamen vor ein paar Nächten in mein Lager.",
    ["A crafted helm that outlived several tiers of raid gear. Its plans were the thing guilds actually fought over."] = "Ein gefertigter Helm, der mehrere Stufen von Raid-Ausrüstung überdauerte. Seine Pläne waren das, worüber sich die Gilden tatsächlich stritten.",
    ["Son of Blackhand and the last warchief of the Dark Horde, still holding Blackrock Spire long after the rest of the Horde moved on."] = "Sohn von Blackhand und letzter Kriegshäuptling der Dunklen Horde, der die Schwarzfelsspitze noch lange hielt, nachdem der Rest der Horde weitergezogen war.",
    ["The vindicator's symbol of power is the breastplate."] = "Das Symbol der Macht des Rächers ist der Brustpanzer.",
    ["Wreak havoc on the minions of evil. Zul'Gurub must taste Zandalar vengeance."] = "Richtet Verwüstung unter den Dienern des Bösen an. Zul'Gurub muss die Rache der Zandalar kosten.",
    ["Vengeance is power. The Zandalar vindicator is such power."] = "Rache ist Macht. Der Zandalar-Rächer ist solche Macht.",
    ["A stone giant pressed into qiraji service, who drains the mana of everyone fighting him and turns to rock when full."] = "Ein Steinriese, in den Dienst der Qiraji gezwungen, der allen Gegnern das Mana entzieht und zu Stein wird, wenn er voll ist.",
    ["During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of armor worn by heroes."] = "Solltet Ihr bei Euren Kämpfen gegen die Geißel in Naxxramas entweihte Zinnen und kriegsgezeichnete Plattenreste finden, bringt sie mir zurück, und ich fertige Euch ein Rüstungsteil, wie es Helden tragen.",
}) do text[k] = v end
